  AvgDialog_100303_Content_1 = {
    Text = "Hah... hah... Hayır, bu değil... hâlâ bir şeyler ters geliyor..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Neden tam karşımdayken, ben yine de onu bulamıyorum..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Endişelenme, Pickman. Madem İlham Perisi sana çoktan söyledi, demek ki cevap sana son derece yakın. Dikkatlice düşün, neleri gözden kaçırmış olabilirsin."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Ondan önce, önce seni kaldıralım... Ah..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "Elini hızla geri çekersin. Haşlanmış bedeninin içinde lav gibi akan bir şey hissedersin."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Beklendiği gibi, yine baş belası Thais..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... Ah! Evet! Bunu nasıl düşünemedim! Bunu nasıl göz ardı ettim!!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Birden doğrulur; neredeyse yakıcı olan bakışı doğrudan sana kilitlenir."
  },
  AvgDialog_100303_Content_17 = {
    Text = "En çılgın arzu... evet! Anlıyorum, anlıyorum..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "Ayağa kalkmayı unutacak kadar heyecanlanır, dört ayak üzerinde sana doğru sürünür."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Koruyucu, bir kez daha modelim olur musun? Lütfen! Bu son sefer!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman?"},
  AvgDialog_100303_Content_20 = {
    Text = "Ne yapmak istediğini biliyorum, asla olmaz..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Pickman’in kaygılı ve yalvaran kırmızı gözleri loş ışıkta hafifçe titreşir. Artık reddedici sözleri söyleyemediğini fark edersin."
  },
  AvgDialog_100303_Content_22 = {
    Text = "...Peki. Sadece modelin olacaksam. Yine o kanepede mi oturmalıyım?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "Hayır, hayır, Koruyucu! Böyle bir tablo stüdyoda yaratılamaz!"
  },
  AvgDialog_100303_Content_24 = {Text = "..."},
  AvgDialog_100303_Content_25 = {
    Text = "Bu... resmindeki dünya mı?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "Aynen öyle! Bu, gulyabani karnavalının ayini!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "Onu yarattım, ama asla tamamlamadım. Merkezinde bir çift başrol eksik. Onlar bu evrenin en ilkel ve en vahşi arzularını temsil ediyor, benim unuttuğum arzuları..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "Şimdiye dek başrol olmaya yetecek bir model bulamadım..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pickman diz çökmüş hâlini korur, dizini sürüyerek sana daha da yaklaşır."
  },
  AvgDialog_100303_Content_3 = {
    Text = "Pickman’in loş atölyesi her zamankinden daha da dağınık; her köşeye rastgele saçılmış, renkler ve çizgilerle dolu sayısız deri parçası, sanki tuhaf bir savaşın içinden geçmiş gibi."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Lütfen, Koruyucu... bana İlham Perisi’ni bahşet!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "Bana her şeyi yaptırabilirsin! LÜTFEN! Lütfen bu tabloyu tamamlamama yardım et..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Uzun süre tereddüt etmeden hafifçe iç çekip ona doğru yaklaşırsın."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Başını kaldırır ve kocaman açılmış gözlerle sana bakar. O gözler aynı anda hem açgözlü, hem özlem dolu, hem itaatkâr, hem de sadık bir yaratığa aittir—bir yaban hayvanına ya da adanmış bir evcil hayvana. Sana yalvarmaktadır, onu İlham Perisi’ne götürecek bir buyruk için yakarmaktadır."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Her şey, öyle mi... Öyleyse, dikkatlice düşünmem gerekecek..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "Elin usulca Pickman'ın yüzüne konuyor. Sıcak nefesi hâlâ teninde, ama bedeni bir anda uysallaşıyor. Onu ehlileştiriyor musun, yoksa o mu seni eritiyor, bilmiyorsun."
  },
  AvgDialog_100303_Content_36 = {
    Text = "Gul’ların sesleri yavaşça silinip yerini, tablonun içindeki dünyada yankılanan, başkahramanların kaba ve ilkel seslerine bırakıyor."
  },
  AvgDialog_100303_Content_37 = {
    Text = "Bu, İlham Perisi’nin sesidir."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Üstü başı dağılmış hâlde, iki dizinin üzerine çökmüş, boş bir kâğıdın üzerinde çılgınca karalıyor, neredeyse yırtacak. Sıçramış boya bedenini kaplıyor; vahşi bir ayinin ortasındaki bir mümini andırıyor."
  },
  AvgDialog_100303_Content_5 = {
    Text = "Neler oluyor..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "Duydum, Koruyucu! İlham Perisinin sesini duydum! Tam kulağımın dibinde!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "Gözlerim, ellerim, kalbim, bedenimdeki her hücre onun sesiyle titriyor!"
  },
  AvgDialog_100303_Content_8 = {
    Text = "Çok yaklaştım! En büyük sanata yalnızca bir adım kaldı!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Ama onu bulamıyorum... katliam, fetih, oburluk, tamah, israf, boşluk... Tüm deliliği resmettim, ama hâlâ onu bulamadım..."
  },
  AvgDialog_100588_Content_1 = {
