  },
  AvgDialog_10123_Content_1 = {
    Text = "Saat Kulesi’nin altındaki gizli bir kapıdan süzülüyor, gizlenmiş bir geçide adım atıyorsun."
  },
  AvgDialog_10123_Content_10 = {Text = "..."},
  AvgDialog_10123_Content_11 = {
    Text = "Büyük kapı yavaşça aralanır ve gözlerine yasaklı kutsal mekâna dair ilk manzarayı sunar."
  },
  AvgDialog_10123_Content_13 = {
    Text = "Işık saçan üst bedenleri kara bataklığın üzerinde süzülür; mürekkep karası karanlık, yalnızca onların kör edici saflığını daha da belirginleştirir."
  },
  AvgDialog_10123_Content_14 = {
    Text = "Büyülenmiş halde, insanlıktan uzak varlığa bakakalıyorsun; Silueti, Anahtar Mezarı’nda trans hâlindeyken gördüğün genç kadınınkiyle bir anlığına üst üste biniyor."
  },
  AvgDialog_10123_Content_15 = {
    Text = "Yüzleri yoktur, yine de duruşları derin bir merhamet yayar."
  },
  AvgDialog_10123_Content_16 = {
    Text = "En Yüce. En Saf. En Asil. En Güzel."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Sen... geldin...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "Solgun canavar, kısık bir çığlık salıyor; kükreme ile inilti birbirine sarmaş dolaş."
  },
  AvgDialog_10123_Content_19 = {
    Text = "Kesinlikle insan dili değildi, yine de ne demek istediklerini kusursuzca anlıyorsun."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Kukla ilerliyor; her adımında ayakları metal yürüyüş yoluna çınlayarak vuruyor."
  },
  AvgDialog_10123_Content_20 = {
    Text = "Görüş alanın bulanıklaşıyor ve beklenmedik bir yanma gözlerini sızlatıyor. Sıcak damlalar yanaklarından aşağı izler çiziyor."
  },
  AvgDialog_10123_Content_21 = {
