  },
  AvgDialog_10123_Content_30 = {
    Text = "Tawil’in seni hâlâ kovmamış olması... yalnızca kaderinin artık Mythag’ınkiyle bağlandığı anlamına gelebilir."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Bu yüzden, bunu duymaya hak kazandın."
  },
  AvgDialog_10123_Content_32 = {
