  },
  AvgDialog_10123_Content_40 = {
    Text = "Yumurtadan çıkan bir yavrunun titremesini andıran bir sarsıntıyla, bedenlerinden altı görkemli gümüş kanat fışkırdı."
  },
  AvgDialog_10123_Content_41 = {
