  },
  AvgDialog_10123_Content_42 = {
    Text = "Parıldayan madde havuzun zifiri siyahıyla buluştuğunda, su kudurmuşçasına kabarıyor. Derinliklerinden Grotesk Çözünmüşler beliriyor."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Akıl almaz iğrenç yaratıklar Saçılma’ya uğrar; bazıları grubunuza saldırırken, geri kalanlar Saat Kulesi meydanına doğru taşar."
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Nihayet... buldum... seni...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "Onları durdurmalıyız! Daha fazla Canavar’ın ortaya çıkmasını engellemenin tek yolu bu!"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Kara Havuz’un dibindeki <Yellow:Çekirdek> denen devasa Gümüş eser olmadan, Uyandırıcı teknolojimiz onlarca yıl geriye giderdi. İnsan ruhları tek başına onları ayakta tutamayacak kadar kırılgan."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Yani bağlantısız Uyandıranlar üzerindeki kısıtlama... bizi deliliğe yenik düşmekten korumak için mi?"
  },
  AvgDialog_10123_Content_7 = {
