  },
  AvgDialog_10123_Content_8 = {
    Text = "Tamam, geldik."
  },
  AvgDialog_10123_Content_9 = {
    Text = "Konuşurken, Doll duvardaki göze çarpmayan bir düğmeye basar. Keskin bir zil sesi çınlar ve kapı kayarak açılır, ötesinde dar ve loş bir oda ortaya çıkar."
  },
  AvgDialog_10124_Content_1 = {
    Text = "Ritmini bulmuş gibisin. Komut sende, Koruyucu!"
