  AvgDialog_10125_Content_1 = {
    Text = "Off. Üzgünüm, tüm bunlara usulünce alışman için vaktin yok."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona dehşete kapılmış görünüyor; onu hiç bu kadar telaşlı görmemiştin."
  },
  AvgDialog_10125_Content_11 = {
    Text = "Sorularla bombardımana tutulan kız, sesi titreyerek konuşuyor; yorgunluğu her hâlinden belli."
  },
  AvgDialog_10125_Content_12 = {
    Text = "Onu tanıyorsun—<Blue:Uyandırma Araştırma Enstitüsü>’ne bağlı, iletişim kurması nam salmış derecede zor Profesör Doll. Yani, savaşçı olmayan biri."
