  AvgDialog_10125_Content_13 = {
    Text = "Elbette. Buraya keyifli bir gezinti için geldiğimi mi sandın?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Gözlerini kapatıyor, kendini hızla toparlıyor."
  },
  AvgDialog_10125_Content_15 = {
    Text = "Anahtar Mezarı da mı ihlal edildi? Arka çıkışa yakınız. Siz ikiniz derhal tahliye olun."
  },
  AvgDialog_10125_Content_16 = {
    Text = "Biz yardımcı olabiliriz! %player% bizimle bir bağ kurup komutayı ele alabilir—"
