  AvgDialog_18796_Content_3 = {
    Text = "Tadaa! Ne dersiniz? Muhteşem değil mi!"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Bu geçiş genellikle aynı sahneler arasında geçiş yapmak için kullanılır, bilirsiniz."
