  AvgDialog_18796_Content_7 = {
    Text = "Sonra... 3 Numaralı Geçiş!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "3 Numaralı Geçiş de parlak sahnelere geçiş için uygundur, ancak temposu biraz daha yavaş olacaktır, hehe."
