  AvgDialog_18797_Content_1 = {
    Text = "Hmm... @1... Ugh..."
  },
  AvgDialog_18797_Content_10 = {
    Text = "Sen \"Tanrı Kral\" değil misin!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Sonuçta, Miryam'ın hizmet ettiği kişi olarak, Tanrı'nın dirilişi kehanetini ilan eden sen değil miydin?"
  },
  AvgDialog_18797_Content_12 = {Text = "Sen..."},
  AvgDialog_18797_Content_13 = {
    Text = "Az önce gördüm... bağlantı aracılığıyla, senin anılarını gördüm"
  },
  AvgDialog_18797_Content_14 = {Text = "...Evet."},
  AvgDialog_18797_Content_15 = {
    Text = "Bu benim bahşettiğim kehanet, ancak sözde \"ilahi vahiy\" diye bir şey mevcut değil."
  },
  AvgDialog_18797_Content_16 = {Text = "Ne?"},
  AvgDialog_18797_Content_17 = {
    Text = "Tufan gelmeden çok önce, O’nun rüyasından geleceğe göz atma yeteneğimi kaybettim./nNereye gittiğini bilmiyorum; uyanmış da olabilir, çekip gitmiş de."
  },
  AvgDialog_18797_Content_18 = {
    Text = "O hâlde, kehanetin..."
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam, İlahi Diyar için doğmuş, Benim irademle sürüklenen, son derece dindar bir mümindir."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy acılı bir inleme çıkardı, mırıltıları kopuk kopuktu."
  },
  AvgDialog_18797_Content_20 = {
    Text = "Tek umudum, sözlerimin onun son anlarında teselli olmasıydı; onların kutsal yasa gibi alınacağını ve İlahi Diyar’ı yeniden inşa etmeye kalkışacağını asla beklememiştim."
  },
  AvgDialog_18797_Content_21 = {Text = "Hepsi..."},
  AvgDialog_18797_Content_22 = {
    Text = "Tamamen benim suçum."
  },
  AvgDialog_18797_Content_23 = {
    Text = "Geri sayım: 60 dakika"
  },
  AvgDialog_18797_Content_3 = {Text = "Bu da ne?!"},
  AvgDialog_18797_Content_4 = {
    Text = "Murphy'nin yüzünde korkunç koyu yeşil izler belirdi, bitki kökleri gibi derisinin altına derinlemesine gömülmüştü."
  },
  AvgDialog_18797_Content_5 = {
    Text = "Ev sahibinin kan akışını engellemeye başlıyor."
  },
  AvgDialog_18797_Content_6 = {
    Text = "Gök cisimlerinden uzak durmanın yeterli olacağı söylenmiyor muydu?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Demek istediğim, belki daha az acı çekerdi."
  },
  AvgDialog_18797_Content_8 = {
    Text = "Göksel yörüngeye ulaşıldı; artık geri dönüş yok."
  },
  AvgDialog_18797_Content_9 = {
    Text = "Gerçekten hiç çözüm yok mu?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Hah... Hah... Üstte bir şey yok, altta da yok..."
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy anında gücünü kaybetti, geminin küpeştesine yaslanarak güverteye kaydı, artık hanımefendi duruşunu korumayı umursamıyordu."
  },
  AvgDialog_18798_Content_11 = {
    Text = "Tutunacak bir şey bulmak istedi. Biraz el yordamıyla aradıktan sonra senin omzuna yaslandı."
  },
  AvgDialog_18798_Content_12 = {
    Text = "Sadece bir dakika..."
  },
  AvgDialog_18798_Content_13 = {
    Text = "Sadece birkaç saniye içinde, hızlı ama ritmik bir nefes alış verişi kulaklarına ulaşır.\n\nMurphy bir kez daha bilincini yitirir."
  },
  AvgDialog_18798_Content_14 = {
    Text = "Giderek zayıflıyor..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "İrtibat kurduğum Tanrı, sayısız yıldızdan gelir. Sırf bir kopyası bile insan direncinin ötesindedir."
  },
  AvgDialog_18798_Content_16 = {
    Text = "Bunu hafifletmenin bir yolu yok mu?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "...Onu aşağı indir."
  },
  AvgDialog_18798_Content_18 = {
    Text = "Gök cisimlerinden uzak dur, belki daha iyi hisseder."
  },
  AvgDialog_18798_Content_2 = {
    Text = "Nerede... hah... onlar?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Ugh... Bu gemi neden bu kadar kocaman...>"
  },
  AvgDialog_18798_Content_4 = {
    Text = "İyi misin?"
  },
  AvgDialog_18798_Content_5 = {
    Text = "Ben gayet iyiyim! Öhö, öhö..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy sana cevap vermek için sesini yükseltir, ama yanlışlıkla yutkunup şiddetle öksürmeye başlar."
  },
  AvgDialog_18798_Content_7 = {
    Text = "Ama gerçekten yorgunum ve başım biraz ağrıyor."
  },
  AvgDialog_18798_Content_8 = {
    Text = "Konuşurken çoktan olduğun yere oturdun."
  },
  AvgDialog_18798_Content_9 = {
    Text = "Şey... biraz dinlenelim, sadece bir anlığına..."
  },
  AvgDialog_18802_Content_1 = {
    Text = "Keşke biraz daha güçlü olsaydım, ona her zaman karşı koyabilseydim...\nAma yapamıyorum, yapamıyorum işte."
  },
  AvgDialog_18802_Content_10 = {
    Text = "Özür dilerim... Özür dilerim... Hep benim... Hep benim hatam..."
  },
  AvgDialog_18802_Content_11 = {
    Text = "Ben işe yaramaz bir canavarım. Bunca insanın ölümüne sebep oldum, ama Jenkin'in kız kardeşini kurtaramadım."
  },
  AvgDialog_18802_Content_12 = {
    Text = "Alınıp götürüldü, götürüldü... ama nereye gittiğini bile bilmiyorum...\nBizi kimin kontrol ettiğini bile bilmiyorum..."
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona, Aigis'in önünde diz çöktü ve kızı nazikçe kollarına aldı."
  },
  AvgDialog_18802_Content_14 = {
    Text = "Elinden gelenin en iyisini yaptın, Aigis. Bu senin hatan değil."
  },
  AvgDialog_18802_Content_15 = {
    Text = "Gerçek Karındeşen buydu, seni kontrol eden ve bu suçları işleyen kişi. \nBu asla senin suçun değildi."
  },
  AvgDialog_18802_Content_16 = {
    Text = "Kız kendini Ramona'nın kollarına attı, kontrolsüzce hıçkırarak ağlıyordu ama sağ eliyle gözlerini örtmeyi asla unutmadı."
  },
  AvgDialog_18802_Content_17 = {
    Text = "O kişiyi bulacağız."
  },
  AvgDialog_18802_Content_18 = {
    Text = "Onu bulacağız ve bedelini ödeteceğiz.\nSana söz veriyorum."
  },
  AvgDialog_18802_Content_19 = {
    Text = "Teşekkür ederim, hepinize teşekkür ederim... Teşekkürler."
  },
  AvgDialog_18802_Content_2 = {
    Text = "Geçen sefer ona karşı koymaya çalıştım, ama... ama... yapamadım. Hıçkırık..."
  },
  AvgDialog_18802_Content_20 = {
    Text = "Batan güneşin altın ışınları, saat kulesinin devasa şeffaf kadranından içeri süzülerek kızın üzerine bir parıltı yayıyor."
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis yana döndü, bir elini cama koyarak sıcak güneş ışığına doğru gözlerini kıstı."
  },
  AvgDialog_18802_Content_22 = {
    Text = "Bugün güneşi görebiliyorum..."
  },
  AvgDialog_18802_Content_24 = {
    Text = "Belki de nadir görülen güneşli günden güç alarak, sendeleyerek daha temiz bir cam parçasına ilerliyor."
  },
  AvgDialog_18802_Content_25 = {
    Text = "Bulanık Görüş Alanı netleşiyor. Tanıdık ve yabancı sokaklara bakarken, birinin kulağına fısıldadığı hissine kapılıyor."
  },
  AvgDialog_18802_Content_26 = {
    Text = "<Italic:\"Bak,\"> diyor o Ses, <Italic:\"Sana söylemiştim. Bu gece çok güzel Yıldızlar olacak.\">"
  },
  AvgDialog_18802_Content_28 = {
    Text = "Kız başını eğdi, hüzünlü bir gülümseme belirdi yüzünde."
  },
  AvgDialog_18802_Content_29 = {
    Text = "Eskiden, güneş göründüğü zamanlarda Tyog beni gizlice gece buraya çıkarırdı."
  },
  AvgDialog_18802_Content_3 = {
    Text = "Dur. Beni bunu yapmaya zorlamayı bırak."
  },
  AvgDialog_18802_Content_30 = {
    Text = "Sarah Hanım buraya gelmemize asla izin vermezdi; çok tehlikeli olduğunu, kolayca yaralanabileceğimizi söylerdi. Ama Tyug bunların hiçbirini umursamazdı."
  },
  AvgDialog_18802_Content_31 = {
    Text = "Gözleri çok iyidir; yer ne kadar karanlık olursa olsun yolu net görebilir."
  },
  AvgDialog_18802_Content_32 = {
    Text = "Tıpkı Jenkin gibi zeki ve cesurdur. Başkalarının bilmediği gizli patikaları ve kestirmeleri her zaman o bilir."
  },
  AvgDialog_18802_Content_33 = {
    Text = "O yanımda olduğu sürece, Bayan Sarah asla bizi bulamazdı."
  },
  AvgDialog_18802_Content_34 = {
    Text = "O yanımda olduğu sürece, burası daima bizim Sırrımız olan saklanma yerimiz olurdu."
  },
  AvgDialog_18802_Content_35 = {
    Text = "Büyümü güçlendirmek için yıldızlarla bağlantı kurmam gerektiğini söyledi. \nHer ne kadar burada tek bir yıldız bile göremesek de."
  },
  AvgDialog_18802_Content_36 = {
    Text = "O zamanlar bana inanan tek kişi oydu.\nO karanlık şeyleri görebildiğime inanıyordu ve bunun bir cadının armağanı olduğunu söylüyordu."
  },
  AvgDialog_18802_Content_37 = {
    Text = "Sonra... ondan sonra doktorlar hastaları götürmeye başladı, artık onları yoksullar evinde tedavi etmiyorlardı. Kanıt toplayamadım ya da Tiyoug'un intikamını alamadım."
  },
  AvgDialog_18802_Content_38 = {
    Text = "Onun kadar zeki ve Jenkin kadar cesur olsaydım, muhtemelen şimdiye kadar gerçeği ortaya çıkarmıştım."
  },
  AvgDialog_18802_Content_39 = {
    Text = "Ama ben bir cadı değilim."
  },
  AvgDialog_18802_Content_4 = {
    Text = "Kimseyi incitmek istemiyorum ve öldürmek de istemiyorum."
  },
  AvgDialog_18802_Content_40 = {
    Text = "Ben sadece bir korkağım."
  },
  AvgDialog_18802_Content_41 = {
    Text = "Bir canavar."
  },
  AvgDialog_18802_Content_42 = {
    Text = "Bir... katil."
  },
  AvgDialog_18802_Content_43 = {
    Text = "Kaç kez manipüle edildiğimi biliyor musun?\nEllerimde ne kadar kan lekesi olduğunu biliyor musun?"
  },
  AvgDialog_18802_Content_44 = {
    Text = "Olmak üzere olduğum şeyden dehşete düşüyorum..."
  },
  AvgDialog_18802_Content_46 = {
    Text = "Eskiden gözlerimde ve vücudumda acı hissederdim. Ama şimdi hiçbir şey hissetmiyorum, sanki taştan yapılmışım gibi."
  },
  AvgDialog_18802_Content_48 = {
    Text = "Lanet olsun, herkes nereye gitti..."
  },
  AvgDialog_18802_Content_49 = {
    Text = "Bekle, bu da..."
  },
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:Hayır! Hayır!\nKüçük Mike'a bunu yaptırmayın. O çok küçük. Nasıl yapabilir... <Shake:Lütfen...>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "Aniden, saat kulesinin altından Jenkin'in sesi geldi. Bir şekilde avluda belirmişti."
  },
  AvgDialog_18802_Content_52 = {
    Text = "Endişeyle Aigis'in adını haykırdı, kollarını gökyüzüne doğru uzattı."
  },
  AvgDialog_18802_Content_53 = {
    Text = "Kızın küçük bedeni düşerek gece gökyüzünden sonsuza dek kayboldu."
  },
  AvgDialog_18802_Content_54 = {
    Text = "Bir kuş gece göğünü kat ediyor, yoğun sise karışıp iz bırakmadan kayboluyor."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Jenkin'in uzattığı kolları yalnızca Aigis'in boş elbisesini tutuyordu, kar taneleri gibi kare kağıt parçaları saçılıyordu."
  },
  AvgDialog_18802_Content_56 = {
    Text = "Ai... Aigis...?\nNasıl... bu nasıl olabilir...?"
  },
  AvgDialog_18802_Content_57 = {
    Text = "Kağıdın üzerinde altın bir kelebek çizilmiş, kırışık kenarları özenle düzeltilip katlanmış. Düşerken tatlı bir şeker kokusu taşıyor."
  },
  AvgDialog_18802_Content_58 = {
    Text = "Ah... Aigis..."
  },
  AvgDialog_18802_Content_59 = {
    Text = "Kan lekeli bir kurdele, bir şeker kağıdıyla birlikte kızın eline düştü. Rüzgârla sallanarak parmak uçlarına hafifçe dokunuyordu, tıpkı birinin sunduğu nazik bir teselli gibi."
  },
  AvgDialog_18802_Content_6 = {
    Text = "Duyamıyorum, duyamıyorum, duyamıyorum, duyamıyorum, duyamıyorum—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "Kız gözlerini kırptı ve gözyaşları görüşünü bulanıklaştırdı, sessizce o canlı kırmızı tarafından yakalandı."
  },
  AvgDialog_18802_Content_61 = {
    Text = "Bu tanıdık renk, bu tanıdık doku—hatırladığıyla mükemmel bir şekilde eşleşmesi için sadece bir gümüş toka eksik."
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Abla...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = "Başardık mı? İşe yaradı mı?\nÇabuk, kaç, ama lütfen kimseye söyleme."
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Bekle, bu da ne?! Başım, başım...\nAh... ah...!<Shake:Ahhh!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Özür dilerim... Çok özür dilerim..."
  },
  AvgDialog_18804_Content_1 = {
    Text = "Saygın bir Koruyucu olarak, birkaç sıradan çocuk tarafından tamamen alt edildiniz. Bir yıllık eğitim boşa gitti. Devlet okulu birinci sınıf öğrencileri bile sizden daha akıllı."
  },
  AvgDialog_18804_Content_2 = {
    Text = "Hırsızın görev bölgesinde olması şansınızdı. Yoksa, şansınız yaver gitmezdi. Görev süresini kişisel meselelerinize harcamanıza izin vermem."
  },
  AvgDialog_18804_Content_3 = {
    Text = "O kadar da kötü değil, Doll. %player% biraz güven ver."
  },
  AvgDialog_18804_Content_4 = {
    Text = "Lütfen Koruyucu'nun soruşturmasına müdahale etmeyin."
  },
  AvgDialog_18805_Content_1 = {
    Text = "Saygın bir Koruyucu olarak, birkaç sıradan çocuk tarafından tamamen alt edildiniz. Bir yıllık eğitim boşa gitti. Devlet okulu birinci sınıf öğrencileri bile sizden daha akıllı."
  },
  AvgDialog_18805_Content_2 = {
