  AvgDialog_18809_Content_1 = {
    Text = "\nMurphy fazla tereddüt etmedi; Ramona'yı kenara çekip giysilerini çözmeye başladı.\nÖndeki son düğme de açılınca, Ramona kızın içindeki \"tanrı\"yı gördü."
  },
  AvgDialog_18809_Content_2 = {
    Text = "Göğsünde açıkça görülebilen saydam bir deri parçası, çevresindeki deri ve kasları gererek tüm göğüs ve karın bölgesinin grimsi, çürümüş beyaz bir renk almasına neden oluyordu."
  },
  AvgDialog_18809_Content_3 = {
    Text = "Böyle bir anomali göğsündeki organları açığa çıkarmıştı; Ramona soluk kırmızı genç bir kalp ve süt beyazı bir \"yumurta\" gördü."
  },
  AvgDialog_18809_Content_4 = {
    Text = "Sayısız ince iplikçik yumurtadan filizleniyor, Murphy’nin kan damarlarıyla iç içe geçerek simbiotik bir dansa tutuşuyordu."
  },
  AvgDialog_18809_Content_5 = {
    Text = "Kalbine bastırma biçimi olmasaydı, onun saydam bedeninin doğal bir parçası sanılabilirdi; yabancı bir istilacı değil."
  },
  AvgDialog_18809_Content_6 = {
    Text = "Kaotik ama sessizdi; üzerinde donmuş, ters çevrilmiş bir üçgen oluşturan siyah işaretler taşıyordu; grotesk bir sanat eseri gibi."
  },
  AvgDialog_18809_Content_7 = {
    Text = "Çözünme… o şey Çözünme tarafından damgalanmış."
  },
  AvgDialog_18809_Content_8 = {
    Text = "Bakmaya doydun mu?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Özür dilerim, benim hatam. Lütfen giysilerini giy."
  },
  AvgDialog_18810_Content_1 = {
    Text = "Geri sayım: 20 dakika"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Dikkat! Denize düşmeyin!"
  },
  AvgDialog_18810_Content_11 = {
    Text = "Devasa bir yılan denizden fırladı, neredeyse tüm gemiyi alabora ediyordu.\nBirden fazla yılan başı kıvranıp bükülüyor, güverteye büyük, uğursuz gölgeler düşürüyordu."
  },
  AvgDialog_18810_Content_12 = {
    Text = "Gasıp... Küstah... Ahmak!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Tanrıça... Tanrıça... @3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Eyvah, bu Miryam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Murphy'yi çabuk indirin!"
  },
  AvgDialog_18810_Content_16 = {Text = "Ugh!!"},
  AvgDialog_18810_Content_17 = {
    Text = "Güverteye dönüp bakarsın; Murphy artık orada değildir. Devasa bir yılan başı kızı yakalamış, onu denizin dibine sürüklemiştir."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Bağlantı mı? Yani bundan sonra hayatta kalmak için sana bağımlı mı olacak?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "Bu sadece geçici bir önlem. Bayan Celeste'i sizden almak gibi bir niyetimiz yok."
  },
  AvgDialog_18810_Content_4 = {
    Text = "Bu benim karar verebileceğim bir şey değil."
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, istekli misin?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Sanki bir anahtar kelimeyle tetiklenmiş gibi, Celeste başını kaldırdı ama bakışlarını arkasındaki denize çevirdi ve yolculuk durdu."
  },
  AvgDialog_18810_Content_7 = {
    Text = "Gemi hareket edemiyor."
  },
  AvgDialog_18810_Content_8 = {
    Text = "Bir şey beni yakaladı."
  },
  AvgDialog_18810_Content_9 = {
    Text = "Sözler bitmeden, yer daha önce hiç olmadığı kadar şiddetli sallandı ve gemi akıl almaz bir açıyla eğildi."
  },
  AvgDialog_18812_Content_1 = {
    Text = "Siz bile... Bir avuç bencil yetişkin."
  },
  AvgDialog_18812_Content_10 = {
    Text = "Göz alıcı ışık gözlerini sızlatıyor, istemsiz yaşlar boşalıyor."
  },
  AvgDialog_18812_Content_11 = {
    Text = "Bu, bu da ne!?"
  },
  AvgDialog_18812_Content_12 = {
    Text = "Bulanık sıvı çekilip giderken, gözlerin nihayet kız çocuğuna yeniden odaklanıyor."
  },
  AvgDialog_18812_Content_13 = {
    Text = "Bıçak göğsüne derinlemesine gömülüyor ve ay ışığı altındaki kız çocuğu gözlerini açıyor."
  },
  AvgDialog_18812_Content_14 = {
    Text = "Ölümün simgesi dolunay yaklaşmış, tepende asılı duruyor; yine de genç yüzünde en ufak bir dehşet izi yok."
  },
  AvgDialog_18812_Content_15 = {
    Text = "Ben... onu deldim... Doğmayacak..."
  },
  AvgDialog_18812_Content_16 = {
    Text = "O zaman... Onlar..."
  },
  AvgDialog_18812_Content_17 = {
    Text = "Bıçağı kavrayan el güçsüzce düşüyor; kızıl, koyu ve yoğun bir sıvı bıçaktan akarak parmaklarının arasından denize damlıyor."
  },
  AvgDialog_18812_Content_18 = {
    Text = "Kan hızla bedenden boşalıyor, cilt ölümcül bir solgunluğa bürünüyor, ama içeriden olağandışı bir canlılık yayılıyor."
  },
  AvgDialog_18812_Content_19 = {
    Text = "Hayır... Hayır, hayır, hayır, hayır, aahh—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Kimse benim fikrimi sormadı... Hmph."
  },
  AvgDialog_18812_Content_20 = {
    Text = "Ey Rab, beni bağışla, bu çocuğu bağışla, dindar müminini bağışla..."
  },
  AvgDialog_18812_Content_21 = {
    Text = "Yıldızların Düz Konumu, yakın... Çok yakın..."
  },
  AvgDialog_18812_Content_22 = {
    Text = "\"Plasenta\" paramparça oldu ve \"kalp\" de çöktü—sayısız el bedenden fırladı, kızın göğüs boşluğunu ezerek parçaladı."
  },
  AvgDialog_18812_Content_23 = {
    Text = "Deforme olmuş el tanınmaz haldeki kalıntıları kavradı, üst üste biniyor, şişiyor, üst üste biniyor, şişiyor—"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... Beni duydun... Bana karşılık verdin..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Biçimsiz bir varlığı ay ışığının içine iterler."
  },
  AvgDialog_18812_Content_26 = {
    Text = "Yüce Tanrım...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "Fedakârlıkla satın alınmış bir hayat... Kim ister ki bunu?"
  },
  AvgDialog_18812_Content_4 = {
    Text = "\nHayır, plasenta çok bulanık.\n\"Ruh İzleme\" ile içini görebilir miyim?"
  },
  AvgDialog_18812_Content_5 = {
    Text = "Titreyen Gümüş Anahtar'ı sıkıca kavradın ve bilinç uzamına geri daldın."
  },
  AvgDialog_18812_Content_6 = {
    Text = "D-balçıkla kaplı karanlık, boş uzamda, yaşamı ve zekâyı simgeleyen küçücük bir kıvılcım daha da parlak yanar."
  },
  AvgDialog_18812_Content_7 = {
    Text = "—Bir kurban bıçağı parlar, soğuk, uğursuz ay ışığını yansıtır."
  },
  AvgDialog_18812_Content_8 = {Text = "—AAAH!!"},
  AvgDialog_18812_Content_9 = {
    Text = "Bir ışık patlaması aniden fışkırır, seni zorla ruh alanının dışına savurur."
  },
