  AvgDialog_18956_Content_17 = {
    Text = "Burası da neresi?"
  },
  AvgDialog_18956_Content_18 = {
    Text = "Sesler sorularını görmezden gelir. Kıpırdanır, haykırır ve sana bir davet uzatırlar."
