  AvgDialog_18956_Content_3 = {Text = "Hayır—"},
  AvgDialog_18956_Content_4 = {
    Text = "Yine beyaz balmumunun içine sarılıyorsun."
  },
  AvgDialog_18956_Content_5 = {
    Text = "Mum, sanki hiç doymayacakmış gibi kanı tamahla emer, ta ki tuhaf bir tat algılayana dek."
