  },
  AvgDialog_18956_Content_7 = {
    Text = "Derin bir girdabın içine çekiliyorsun."
  },
  AvgDialog_18956_Content_8 = {
    Text = "Karmaşık anılar önünüzde bir parşömen gibi açılıyor. Neşeli, hüzünlü, acı dolu...\nSadece sizin anılarınız değil, başkalarının da."
  },
  AvgDialog_18956_Content_9 = {
    Text = "Bu... da ne..."
