  AvgDialog_62169_Content_5 = {
    Text = "Baban, Gücün, özgürlüğün ve Can’ın... Hepsini kaybetmek üzeresin, Ramona. Ama ondan önce... hâlâ {Male=onu,Female=onu} varsın."
  },
  AvgDialog_62169_Content_6 = {
    Text = "Evet, Tawil. Kaybetmeyi göze alamayacağım bazı şeyler var... Ona söz verdim {Male=ona,Female=ona}..."
  },
  AvgDialog_62169_Content_7 = {
    Text = "Ramona başını kaldırır, sesin kaynağına doğru bakar."
  },
  AvgDialog_62169_Content_8 = {
    Text = "Ne zaman olursa olsun, ne olursa olsun... {Male=onunla,Female=onunla} birlikte duracağım."
  },
  AvgDialog_62169_Content_9 = {
    Text = "Hameln'in ezgisi ve senin çağrın eşliğinde, siyah-beyaz heykelden titreşen gümüşi bir çiçek süzülür."
  },
  AvgDialog_62208_Content_1 = {Text = "Son Perde"},
  AvgDialog_62208_Content_10 = {
    Text = "Bu, kusursuz bir icranın gururu, en yüce notayı işitme beklentisi."
  },
  AvgDialog_62208_Content_11 = {
    Text = "Yetkilerine alışmak için yeterli zamanın olacak. Yüce İrade geldiğinde, bu dünya onun nihai melodisiyle yankılanacak."
  },
  AvgDialog_62208_Content_12 = {
    Text = "—Yıkım ve sessizlikten ziyade, yaşamın ve zaferin notalarını umuyorum."
  },
  AvgDialog_62208_Content_13 = {
    Text = "Teşekkür ederim."
  },
  AvgDialog_62208_Content_14 = {
    Text = "Entrikaların canımı sıktı... Ama yardımın dokundu. Teşekkür ederim."
  },
  AvgDialog_62208_Content_15 = {
    Text = "Çevirdiğin dolaplardan hoşlanmıyorum."
  },
  AvgDialog_62208_Content_16 = {
    Text = "Çevirdiğin dolaplardan hoşlanmıyorum, Hameln—hiç hoşlanmadım..."
  },
  AvgDialog_62208_Content_17 = {
    Text = "Ama her şeye rağmen, yardım ettin."
  },
  AvgDialog_62208_Content_18 = {
    Text = "Sanırım sana teşekkür borçluyum."
  },
  AvgDialog_62208_Content_19 = {
    Text = "Sadece vasat şefler, seyircinin ne düşündüğünü umursar."
  },
  AvgDialog_62208_Content_2 = {
    Text = "Bu... bitti mi?..."
  },
  AvgDialog_62208_Content_20 = {
    Text = "Kendi amacım için hareket ettim. İşbirlikçilerin arasında teşekküre gerek yok."
  },
  AvgDialog_62208_Content_21 = {
    Text = "Hameln derin bir nefes alıyor, gözleri kapalı, bagetini kaldırıp kaldırıp yerine koymaya hazırlanıyor."
  },
  AvgDialog_62208_Content_22 = {
    Text = "Uzun süren entrikalar bu şef maestroyu bile yormuş görünüyor.\nAlkışsız bu gösteride, son reveransını yapıyor."
  },
  AvgDialog_62208_Content_23 = {
    Text = "Ama bageti yarıya kadar toplandığında, Kapı'dan hafif bir flüt ezgisi süzülüyor."
  },
  AvgDialog_62208_Content_24 = {Text = "!!!"},
  AvgDialog_62208_Content_25 = {
    Text = "Hameln, sen..."
  },
  AvgDialog_62208_Content_26 = {Text = "?!!..."},
  AvgDialog_62208_Content_27 = {
    Text = "Bakışlarını onunla birlikte Kapı'ya çevirdiğinde, onun gibi donup kalıyorsun—hareket edemez, konuşamaz hâle geliyorsun."
  },
  AvgDialog_62208_Content_28 = {Text = "Koruyucu?"},
  AvgDialog_62208_Content_29 = {
    Text = "Ramona sana şaşkınlıkla bakıyor."
  },
  AvgDialog_62208_Content_3 = {
    Text = "Bir baş dönmesi dalgası seni vuruyor. Amansız Savaş'ların ardından biriken Yorgunluk, bir dağ gibi üstüne çöküyor."
  },
  AvgDialog_62208_Content_30 = {
    Text = "Bu sevinç anında, yüzünde daha önce hiç görülmemiş bir ifade görüyor—"
  },
  AvgDialog_62208_Content_31 = {
    Text = "Kozmik çöküşle yüzleşen bir ruhunki..."
  },
  AvgDialog_62208_Content_32 = {
    Text = "Ürperti, dehşet, umutsuzluk, zayıflık."
  },
  AvgDialog_62208_Content_33 = {
    Text = "Bakışlarını takip ederek arkasını dönüyor—"
  },
  AvgDialog_62208_Content_34 = {
    Text = "Bir zamanlar sakin olan Kapı'nın ardında, durağan tonlar paramparça oluyor. Zaman, mekân, Bilgi Kırık Parçalar hâlinde ufalanıp bu Boyut'u, dökülmüş yağ misali kaotik, kirli Ana Renklerle lekeliyor."
  },
  AvgDialog_62208_Content_35 = {
    Text = "Alçak flüt sesleri araya giriyor; ilkel, kaotik bir ezgi Kalabalık'ın arasından kıvrılıp geçiyor, herkesi korkudan bir Koza'ya sarıyor."
  },
  AvgDialog_62208_Content_36 = {
    Text = "Flüt sesinin ve her yanı kaplayan Ana Renklerin ortasında, bir göz yavaşça açılıyor; yeni doğmuş bir Bebek gibi, bu dünyayı merakla süzüyor."
  },
  AvgDialog_62208_Content_37 = {
    Text = "Bakışının düştüğü yerde, sayısız varlık Çözünme sıvılarına çözünüp Kara Havuz'la birleşiyor."
  },
  AvgDialog_62208_Content_38 = {
    Text = "Bakış tarıyor, sonunda üzerinde kilitleniyor."
  },
  AvgDialog_62208_Content_39 = {Text = "...@3..."},
  AvgDialog_62208_Content_4 = {
    Text = "Çöküşün eşiğinde sendeleyip dururken, yumuşak bir melodi seni dengeliyor."
  },
  AvgDialog_62208_Content_40 = {
    Text = "Göz bebeği bir anda keskin biçimde büyür. Kara Havuz kükreyerek coşar; evrenin kendisi sarsılıyormuş gibi gelir."
  },
  AvgDialog_62208_Content_41 = {
    Text = "Onunla göz göze kilitlenirsin; böyle bir bakış, şüphesiz küfürdür. Bilincinden her şey silinip gider."
  },
  AvgDialog_62208_Content_42 = {
    Text = "Dehşet. İlksel, en saf dehşet—akıl almaz, kaçınılmaz—içini baştan aşağı doldurur."
  },
  AvgDialog_62208_Content_44 = {
    Text = "Hehehehe... Hahaha!"
  },
  AvgDialog_62208_Content_45 = {
    Text = "Umut, haz, kavuşma, sonra pat—ölüm."
  },
  AvgDialog_62208_Content_46 = {
    Text = "Mythag'ın köstebeği, dostum, sahnenin en zarif ikinci yardımcısı—sana alkış tutmaktan kendimi alamıyorum!"
  },
  AvgDialog_62208_Content_47 = {
    Text = "Senin hakkında haklıymışım, %player%. Hepiniz hakkında haklıymışım!"
  },
  AvgDialog_62208_Content_48 = {
    Text = "N'nin sesi Kara Havuz'un gölgelerinden belirir. Bu manzara Ondan tüm zarafeti soyup almıştır. Kapıya ateşli bir tutkuyla bakarken çılgınca kahkaha atar."
  },
  AvgDialog_62208_Content_49 = {
    Text = "Uyanıyor, Uyanıyor! Ha!"
  },
  AvgDialog_62208_Content_5 = {
    Text = "Öyle. Gösteri sona erdi, {Male=Bey,Female=Bayan} Koruyucu."
  },
  AvgDialog_62208_Content_50 = {
    Text = "Demek, %player%, Parça, sahtekâr..."
  },
  AvgDialog_62208_Content_51 = {
    Text = "Döner; habis ağzı kulaklarına varan bir sırıtışla açılmış, gözsüz kara yüzü seni oyunbazca süzer."
  },
  AvgDialog_62208_Content_52 = {
    Text = "Söyle bana... şimdi ne yapabilirsin?"
  },
  AvgDialog_62208_Content_6 = {
    Text = "Juliette'in ayini başarısız oldu. Onu yönlendiren alev olmadan, Yüce İrade şimdilik uykuda kalıyor."
  },
  AvgDialog_62208_Content_7 = {
    Text = "Dönüp o serin sesin kaynağına bakıyorsun."
  },
  AvgDialog_62208_Content_8 = {
    Text = "Kapı'nın gücü neredeyse Hameln'in bedenini paramparça etti; kızıl kan giysisini ve bagetini sırılsıklam etmiş, ama o aldırmıyor."
  },
  AvgDialog_62208_Content_9 = {
    Text = "Giysileri kusursuzca düzgün, bageti ve kolu hatasız bir pozisyonda duruyor—fakat o buz kesmiş yüzde sonunda bir gülümseme beliriyor."
  },
  AvgDialog_62342_Content_1 = {
    Text = "Çılgına dönmüş Işıkyolcu Müridleri kabaran Kara Havuz’a çöp gibi yığılıp onunla kusursuzca bütünleşiyor."
  },
  AvgDialog_62342_Content_10 = {
    Text = "Juliette, Heykel’in dibinde duruyor; Onun Gözleri, gözlerinin önünde açılan Mucize’ye hayranlıkla kilitlenmiş."
  },
  AvgDialog_62342_Content_11 = {
    Text = "Heykeller önünde yükseliyor, yeniden şekillenen bir Yaban Hayvanı gibi alçak bir uğultu yayıyor. İlkel, tehlikeli bir aura duyularına Hücum ediyor."
  },
  AvgDialog_62342_Content_12 = {
    Text = "Juliette heykellerin birleşmesini hızlandırıyor... ve Ramona tam orada."
  },
  AvgDialog_62342_Content_13 = {
    Text = "Hameln yanında duruyor; bir El’i batonunda, diğeri arkasında."
  },
  AvgDialog_62342_Content_14 = {
    Text = "Sana başıyla selam veriyor, tıpkı Şarj’dan önce selam duran bir Şövalye gibi."
  },
  AvgDialog_62342_Content_15 = {
    Text = "İleri, {Male=Bay,Female=Bayan} Koruyucu. O Heykel’i parçala, yoldaşını kurtar."
  },
  AvgDialog_62342_Content_16 = {
    Text = "Otorite’ni dünyaya göster... Yüce İrade’ye dair her şeyi hatırla."
  },
  AvgDialog_62342_Content_2 = {Text = "Öhö..."},
  AvgDialog_62342_Content_3 = {
    Text = "Hameln, yanında hafifçe titrer."
  },
  AvgDialog_62342_Content_4 = {
    Text = "Zihnini ayakta tutmak, tarikatçılara karşı Savaş’ına yardım etmek—onu derinden Tükenme’ye sürüklüyor. Ne kadar daha dayanabileceğini merak ediyorsun."
  },
  AvgDialog_62342_Content_5 = {
    Text = "Hameln, yaraların..."
  },
  AvgDialog_62342_Content_6 = {
    Text = "Odaklan. Hedefin önünde, Koruyucu."
  },
  AvgDialog_62342_Content_7 = {
    Text = "Başını kaldırıyor, önündeki devasa yapıya bakıyorsun."
  },
  AvgDialog_62342_Content_8 = {
    Text = "Tazılarım, sadıklarım—yeterince zaman kazandılar.\nYüce Varlık onların fedakârlığını hatırlayacak."
  },
  AvgDialog_62342_Content_9 = {
    Text = "Ne kadar güzel... sence de öyle değil mi, {Male=Bay,Female=Bayan} Koruyucu?"
  },
  AvgDialog_64033_Content_1 = {
    Text = "Asansörden çıktığınızda, yakındaki mağara duvarında siyah, ters üçgen şeklinde bir boşluk uğursuzca beliriyor. Yarık aniden uzayı yırtarak çevredeki havayı titretiyor."
  },
  AvgDialog_64033_Content_10 = {
    Text = "Hayır... Böyle olmamalıydı."
  },
  AvgDialog_64033_Content_12 = {
    Text = "Göğsünüzde belirsiz bir tuhaflık hissi dolanıyor, ama sizi neyin rahatsız ettiğini tam olarak çözemiyorsunuz — yarık mı? Gillan mı? Yoksa belki de..."
  },
  AvgDialog_64033_Content_13 = {
    Text = "Emma Gillan'ın cesedinin yanına çömeliyorsunuz, bulanık gözlerle baktığını görüyorsunuz. O boş gözler yarığa sabitlenmiş, sizin göremediğiniz bir şeye bakıyor, çözülmemiş bir dehşetin izini yayıyor."
  },
  AvgDialog_64033_Content_14 = {
    Text = "Emma Gilan..."
  },
  AvgDialog_64033_Content_15 = {
    Text = "Elinizi uzatıp nazikçe gözlerini kapatıyorsunuz."
  },
  AvgDialog_64033_Content_16 = {
    Text = "Gümüş Anahtar Yolunu Aydınlatsın."
  },
  AvgDialog_64033_Content_17 = {
    Text = "Gümüş Anahtar'ı göğsünde değil; yalnızca nefesi kesildiğinde çatlağı kapatmaya çalışıyor olabileceğini tahmin edebiliyorsunuz."
  },
  AvgDialog_64033_Content_18 = {
    Text = "Derin bir nefes alarak kolundan tutup elini yarıktan çekiyorsunuz—"
  },
  AvgDialog_64033_Content_19 = {Text = "O an."},
  AvgDialog_64033_Content_2 = {
    Text = "Ve okul üniformalı kız sırtı size dönük şekilde diz çökmüş, sağ ön kolu gerçekliğin yırtığına uzanmış, sanki onun tarafından yutuluyormuş gibi."
  },
  AvgDialog_64033_Content_20 = {
    Text = "Parmakları güçsüzce açılıyor ve avuç içi büyüklüğünde gümüş bir küp yere düşüyor."
  },
  AvgDialog_64033_Content_21 = {
    Text = "Kaleydoskopik ışık hızla ve zarif bir şekilde küpü sarıyor, sanki canlıymış gibi akıp girdap yaparak sonunda onu santim santim kaplıyor."
  },
  AvgDialog_64033_Content_22 = {
    Text = "Bir sonraki anda, ışığın yuttuğu küp santim santim ufalanmaya başlıyor, hafif ama belirgin çatırdama sesleri çıkararak."
  },
  AvgDialog_64033_Content_23 = {
    Text = "Sessiz bir patlama aniden gerçekleşiyor, bir yıldızın parçalanması gibi, ve gümüş ışık fışkırarak loş madeni aydınlatıyor."
  },
  AvgDialog_64033_Content_24 = {
    Text = "Anılar zihninizi istila ediyor. Kendinizi azgın bir nehre düşmüş gibi hissediyorsunuz, sayısız duygu ve görüntü bilincize saldırıyor..."
  },
  AvgDialog_64033_Content_25 = {
    Text = "Doll...Elr..."
  },
  AvgDialog_64033_Content_3 = {
    Text = "Emma Gilan? Emma!"
  },
  AvgDialog_64033_Content_4 = {
    Text = "Sesiniz dar maden tünelinde yankılanıyor, ama o size cevap vermiyor."
  },
  AvgDialog_64033_Content_5 = {
    Text = "Kalbiniz hızla çarparken sonunda yanına ulaştınız ve nazikçe omzuna dokundunuz, parmak uçlarınızdan yayılan yalnızca soğuk bir umutsuzluk hissettiniz."
  },
  AvgDialog_64033_Content_6 = {
    Text = "...Doll, kayıp müfettişi buldum ve çatlak da burada."
  },
  AvgDialog_64033_Content_7 = {
    Text = "Artık nefes almıyor."
  },
  AvgDialog_64033_Content_8 = {
    Text = "Normal. Siz maden geçidini yeniden açmadan önce oksijen seviyesi zaten standardın altına düşmüştü."
  },
  AvgDialog_64033_Content_9 = {
    Text = "Yarığı kapat, Gümüş Anahtar'ı al ve geldiğin yoldan geri dön."
  },
  AvgDialog_64034_Content_1 = {
    Text = "Demek gerçekten geldin. Öğrencilerim arasında en hantal olanlardan biri olsan da, sezgilerin bir sokak köpeğininki kadar keskin."
  },
  AvgDialog_64034_Content_10 = {
    Text = "Güler; sesi, sessiz mekânda yankılanırken soğuk bir bıçak gibi tenini tırmalar, ona karşı çıkmaya cüret eden her aptalla alay eder."
  },
  AvgDialog_64034_Content_11 = {
    Text = "Kırık beden gölgelerde titriyor, her parçası çığlık atıyor. Uzuvlar kül gibi ufalanarak ele avuca sığmaz toza dönüşüyor."
  },
  AvgDialog_64034_Content_12 = {
    Text = "Beyin havuzu yeni kabuğuna bağlanırken, eklemler, sanki yeraltı yaratığı zincirlerine karşı geriniyormuşçasına, ilik donduran bir gıcırtıyla sürtünür."
  },
  AvgDialog_64034_Content_14 = {
    Text = "Doll'un gözleri çılgın bir ışıkla parlıyor, dünyanın her köşesini dikkatle inceliyor."
  },
  AvgDialog_64034_Content_15 = {
    Text = "Bakalım bu cevabı ne kadar istiyorsun."
  },
  AvgDialog_64034_Content_2 = {
    Text = "Ama pervasız cesaretin hâlâ beni eğlendiriyor — gerçekten tek başına peşimden mi geldin?"
  },
  AvgDialog_64034_Content_3 = {
    Text = "Diğer müfettişler dışarıda. Yardım çağırırsam hepsi içeri koşar."
  },
  AvgDialog_64034_Content_4 = {
    Text = "Ayrıca, dünya genelindeki müfettişler felaket bölgelerinde kararsız Gümüş kalıntıları buldu."
  },
  AvgDialog_64034_Content_5 = {
    Text = "Sadece sana açıkça sormak istiyorum, yargılanmandan önce, kendi adıma..."
  },
  AvgDialog_64034_Content_6 = {
    Text = "Neden Gümüş bombalar ürettin? Neden dünya genelinde yarıkların ortaya çıkmasına neden oldun? Neden... tüm bunları planladın?"
  },
  AvgDialog_64034_Content_7 = {
    Text = "Neden? Doll."
  },
  AvgDialog_64034_Content_8 = {
    Text = "Depodaki gölgeler gecenin hayaletleri gibi sessizce her köşeye yayılarak havayı tarif edilemez bir soğuklukla dolduruyordu."
  },
  AvgDialog_64034_Content_9 = {
    Text = "Doll'un bedeni zaten ciddi şekilde hasar görmüş, eklem yerlerindeki çatlaklar zamanın yaralarını andırıyordu."
  },
  AvgDialog_64035_Content_1 = {
    Text = "Alistair, Doll'a yaklaşmanızı engellemedi; hatta merkezi uzaklaştırarak konuşmanız için yeterli alan sağladı."
  },
  AvgDialog_64035_Content_10 = {
    Text = "Acıyla yüzünüzü buruşturuyorsunuz, arkanızda Alistair ve Czort'un haykırışlarını duyuyorsunuz, ama şu an tek duyabildiğiniz Doll'un eğlenmiş sesi, kulağınıza fazlasıyla yakın."
  },
  AvgDialog_64035_Content_11 = {
    Text = "Bizim @3 henüz bizi göremiyor..."
  },
  AvgDialog_64035_Content_12 = {
    Text = "Tanıdık duygularla bükülmüş sesi, anlaşılmaz mırıltılara dönüştü."
  },
  AvgDialog_64035_Content_13 = {Text = "...Ne?"},
  AvgDialog_64035_Content_14 = {
    Text = "Bir kez @3’in bakışı gerçekten indiğinde, her şey sona erecek."
  },
  AvgDialog_64035_Content_15 = {
    Text = "Kıyamet gelmeden önce, her zaman Mythag’ın tasmasını çıkarıp bana katılabilirsin."
  },
  AvgDialog_64035_Content_16 = {
    Text = "Tepkinize aldırış etmedi, yalnızca hastalıklı davetine devam etti."
  },
  AvgDialog_64035_Content_17 = {
    Text = "Tutkulu ve samimi, kulağınıza tatlı sözler fısıldayan bir sevgili gibi."
  },
  AvgDialog_64035_Content_18 = {
    Text = "Seni buradan izleyeceğim."
  },
  AvgDialog_64035_Content_19 = {
    Text = "Kısa süre sonra Doll sizden ayrıldı ve daha fazla kısıtlama altına alındı."
  },
  AvgDialog_64035_Content_2 = {
    Text = "Seni baştan çıkarmak ve saptırmak için elinden gelen her şeyi yapacak. Kendi yargına güvenmen gerekiyor."
  },
  AvgDialog_64035_Content_20 = {
    Text = "Hiçbir tepki göstermedi, gerçek bir kukla kadar uysal."
  },
  AvgDialog_64035_Content_21 = {
    Text = "Yalnızca o gözler size sabitlenmiş, her şeyi delip geçerek, daima ruhunuzu takip ediyor."
  },
  AvgDialog_64035_Content_22 = {
    Text = "Özlemle beklenen bir kavuşmayı bekler gibi."
  },
  AvgDialog_64035_Content_3 = {
    Text = "Eğitmenine başını sallayıp Kara Havuz’un derinliklerine doğru ilerliyorsun."
  },
  AvgDialog_64035_Content_4 = {
    Text = "Doll bu kabuğunun içine hapsolmuş, uzuvları kısıtlama cihazlarıyla bağlanmış, dönecek alan bile olmayan bir kafese hapsedilmiş bir canavar gibi. Yine de gözleri hapsedilemeyecek bir çılgınlığı ele veriyor."
  },
  AvgDialog_64035_Content_5 = {
    Text = "Demek... Mythag’ın küçük uşak köpeği gelmiş."
  },
  AvgDialog_64035_Content_6 = {
    Text = "Kısıtlayıcının dibi derin bir karanlık havuzuna gömülüyor; orada ışık yok, yalnızca sonsuz bir sessizlik boşluğu ve onun gelişini bekleyen bilinmeyen bir dehşet var."
  },
  AvgDialog_64035_Content_7 = {
    Text = "Doll, o tablette tam olarak ne gördün..."
  },
  AvgDialog_64035_Content_8 = {Text = "Ugh!"},
  AvgDialog_64035_Content_9 = {
    Text = "Bir gölge gibi fırlıyor, saçlarının arkasından kavrayıp yüzünü omzuna çarpıyor."
  },
  AvgDialog_65470_Content_1 = {
    Text = "Belirleyici: İlksel Gölge"
  },
  AvgDialog_65470_Content_10 = {
    Text = "Thais... Özür dilerim, ben..."
  },
  AvgDialog_65470_Content_11 = {
    Text = "Tsk tsk tsk. Bana karşı atıp tutarken bu kadar bezgin görünmüyordun, sahtekâr."
  },
  AvgDialog_65470_Content_12 = {
    Text = "Başarısız oldun, Gözbebeği Olmayan Göz’ün parçası. Hem de bütünüyle."
  },
  AvgDialog_65470_Content_13 = {
    Text = "Haklısın, N... Başarısız oldum. Onu yenemem..."
  },
  AvgDialog_65470_Content_14 = {
    Text = "Sıradan bir Parça, gerçek Yaratıcı karşısında hiçbir şey yapamaz..."
  },
  AvgDialog_65470_Content_15 = {
    Text = "Üzgünüm, hepinizi hayal kırıklığına uğrattım..."
  },
  AvgDialog_65470_Content_16 = {
    Text = "Hayal kırıklığı mı? Hayır, heyecan içindeyim, %player%. Bu had safhada taşan gösteri büyüleyici oldu."
  },
  AvgDialog_65470_Content_17 = {
    Text = "Elinden gelen her şeyi yaptın, %player%. Beni hiç hayal kırıklığına uğratmadın."
  },
  AvgDialog_65470_Content_18 = {
    Text = "Ve... Senin savaşın henüz bitmedi."
  },
  AvgDialog_65470_Content_19 = {
    Text = "Thais, gözlerinde yumuşak bir gülümsemeyle başını okşar."
  },
  AvgDialog_65470_Content_2 = {Text = "Ko..."},
  AvgDialog_65470_Content_20 = {
    Text = "Bu... bitmedi mi?"
  },
  AvgDialog_65470_Content_21 = {
    Text = "Sayısız başarısızlığın ortasında, zafere giden bir yolun gölgesini gördüm."
  },
  AvgDialog_65470_Content_22 = {
    Text = "Bir yol... bununla özdeş."
  },
  AvgDialog_65470_Content_23 = {
    Text = "Gözlerini kaparsın. Hikmet Çağı'nın Otoritesi içinde Dalgalanma yaratır. Tawil'in hudutsuz düşünceleri zihnini doldurur. Zahmetsizce, Onların Gözleri'nde Fitil Yolu'nu görürsün."
  },
  AvgDialog_65470_Content_24 = {
    Text = "Gözlerin birden açılır, çevrendeki boşluğu tararsın."
  },
  AvgDialog_65470_Content_25 = {
    Text = "Kapıların Ötesinde, Gölge ve ışık fizik kanunlarına meydan okur, Boyutların sınırlarında hafifçe Titreşim hâlinde yanıp söner."
  },
  AvgDialog_65470_Content_26 = {
    Text = "Bunlar... boyutların sınırları... Aralarındaki bariyerleri mi açtın?"
  },
  AvgDialog_65470_Content_27 = {
    Text = "Bu sayısız boyutun her birinde, senin ve benim sayısız versiyonumuz var. Sayısız Koruyucu, sayısız Tawil, aynı düşmanla yüzleşiyor."
  },
  AvgDialog_65470_Content_28 = {
    Text = "Kapı bunların hepsini birbirine bağlıyor... Ve şimdi, tamamen açık."
  },
  AvgDialog_65470_Content_29 = {
    Text = "Artık anlıyorum, Tawil!"
  },
  AvgDialog_65470_Content_3 = {
    Text = "Koruyucu..."
  },
  AvgDialog_65470_Content_30 = {
    Text = "Bu sayısız boyutta Tohuwabohu eşsiz, ama... biz değiliz."
  },
  AvgDialog_65470_Content_31 = {
    Text = "Doğrulursun, o devasa varlığın bakışıyla yüzleşirsin."
  },
  AvgDialog_65470_Content_32 = {
    Text = "Bakın—sahtekâr dostumuz yine {Male=onun,Female=onun} düşüncesizce hamlesine başlamak üzere."
  },
  AvgDialog_65470_Content_33 = {
    Text = "Haklısın, N... Tek bir Parça hiçbir şey yapamaz."
  },
  AvgDialog_65470_Content_34 = {
    Text = "Ama çökmekte olan Yaratıcı Tanrı’nın düşkün parçaları... yalnızca bir tane değiller..."
  },
  AvgDialog_65470_Content_35 = {
    Text = "Kapının içindeki boşluğu tararsın. Sayısız Göz, sayısız Boyuttan sana bakar."
  },
  AvgDialog_65470_Content_36 = {
    Text = "Yine de bilirsin—sana bakmadığını."
  },
  AvgDialog_65470_Content_37 = {
    Text = "O bilinmeyen Boyutlarda, sayısız versiyonun Yaratıcı'nın Gözleri'yle buluşur."
  },
  AvgDialog_65470_Content_38 = {
    Text = "Boyutsal sınırları bütünüyle yırt, Tawil."
  },
  AvgDialog_65470_Content_39 = {
    Text = "Tawil usulca başını sallar ve Ellerini kaldırır."
  },
  AvgDialog_65470_Content_4 = {
    Text = "Sen... Tawil misin?"
  },
  AvgDialog_65470_Content_40 = {
    Text = "İnce bir zar yırtılmış gibi, o sayısız göz, görüş alanında berraklaşıyor."
  },
  AvgDialog_65470_Content_41 = {
    Text = "Zarın yırtıldığı anda, sayısız ses kulaklarına hücum eder."
  },
  AvgDialog_65470_Content_42 = {
    Text = "Hayatımı bir kez zaten kaybettim. Tek bir seçimim var: Bana ait olanı koruyarak ölmek ya da onu terk ederek hayatta kalmak."
  },
  AvgDialog_65470_Content_43 = {
    Text = "\"Yapabilirim. Her ne felaketse bu, O'nun Varışını durduracağım!\""
  },
  AvgDialog_65470_Content_44 = {
    Text = "\"Seni oradan çıkaracağım! ...Ramona, beni bekle!!\""
  },
  AvgDialog_65470_Content_45 = {
    Text = "\"Uyandıranlar—temasa geçin!\""
  },
  AvgDialog_65470_Content_46 = {Text = "..."},
  AvgDialog_65470_Content_47 = {
    Text = "Erkek sesleri. Kadın sesleri. Tutkulu sesler. Ağıt yüklü sesler."
  },
  AvgDialog_65470_Content_48 = {
    Text = "Bu sesler tanıdık ama yabancıdır; ilk kez aynada kendi yüzünü gören bir bebek gibidirler."
  },
  AvgDialog_65470_Content_49 = {
    Text = "Ve o yansıyan bebek artık seni de görüyor."
  },
  AvgDialog_65470_Content_5 = {
    Text = "Ben Tawil'im ve içindeki Hikmet Çağı'nın Otoritesi'yim.\nGüvendesin, Koruyucu."
  },
  AvgDialog_65470_Content_50 = {
    Text = "Bunlar benim seslerim"
  },
  AvgDialog_65470_Content_51 = {
    Text = "Duyuyorum... Bunlar benim seslerim."
  },
  AvgDialog_65470_Content_52 = {
    Text = "Muhteşem, muhteşem... Ben bile sahnede sana katılmaktan kendimi alamıyorum."
  },
  AvgDialog_65470_Content_53 = {
    Text = "Devam edin, sahneye çıkmaya devam edin. Bakalım siz parçalar neler yapabiliyorsunuz!"
  },
  AvgDialog_65470_Content_54 = {
    Text = "Git, Koruyucu... Sana inanmayı seçtim. Hangi kararı verirsen ver, sana yardım edeceğim."
  },
  AvgDialog_65470_Content_55 = {
    Text = "Tawil, Thais, N... Üç Eon'un Gücü sana doğru dalgalanır.\nSen ayağa kalkar, Gümüş Anahtar'ı havaya kaldırırsın."
  },
  AvgDialog_65470_Content_56 = {
    Text = "Alaca bir mekân açılır; Tohuwabohu’nun gözleri belirirken tanıdık sahneler belirmeğe başlar. Sayısız çöken boyutta, sayısız gümüş ışık aynı anda tutuşur."
  },
  AvgDialog_65470_Content_57 = {
    Text = "Gümüş ışıklar Londinium’un balmumu müzesini, Rye’ın sanatoryumunu, Bridgeport’un denizlerini, Remouahe’nin kumlarını aydınlatıyor. Geçmişini, tüm sınavlarını ve büyümeni ışığa boğuyorlar."
  },
  AvgDialog_65470_Content_58 = {
    Text = "O kırılgan, önemsiz parçalar şimdi bıçaklarını Yaratıcı Tanrı’ya doğrultuyor."
  },
  AvgDialog_65470_Content_59 = {
    Text = "Bir göz, bir yara, bir çizik—hatta hiçbir şey... Hiç fark etmez."
  },
  AvgDialog_65470_Content_6 = {Text = "Burası..."},
  AvgDialog_65470_Content_60 = {
    Text = "Bak, Tohuwabohu. Biz senin Parçalarınız, biz Mythag'ın Sır Koruyucuları'yız..."
  },
  AvgDialog_65470_Content_61 = {
    Text = "Bedeli ne olursa olsun, seni burada tutacağız!"
  },
  AvgDialog_65470_Content_7 = {
    Text = "Hikmet Çağı zamanı kısaca geri sardı; hâlâ Kapının içindeyiz."
  },
  AvgDialog_65470_Content_8 = {
    Text = "Tohuwabohu geçmişine göz attı. Ayak bastığın her yerde gözler açıyor. Londinium, Rye, Remouahe..."
  },
  AvgDialog_65470_Content_9 = {
    Text = "O'nun bakışı hâlâ peşimizde."
  },
  AvgDialog_65471_Content_1 = {
    Text = "Rüyanın Çöküşü"
  },
  AvgDialog_65471_Content_10 = {Text = "Dikkat et!"},
  AvgDialog_65471_Content_11 = {
    Text = "Alistair konuşur konuşmaz, Hameln bageti savurur; müzik notaları Tawil ve Ramona geri çekilirken onları Karakter Kalkanı gibi sarar."
  },
  AvgDialog_65471_Content_12 = {
    Text = "Altlarında, Tohuwabohu’nun bakışının oyalanıp durduğu yerde, aniden devasa bir yarık patlak verir."
  },
  AvgDialog_65471_Content_13 = {
    Text = "Altlarında, Tohuwabohu’nun bakışının oyalanıp durduğu yerde, aniden devasa bir yarık patlak verir."
  },
  AvgDialog_65471_Content_14 = {
    Text = "Kara Havuz ansızın açılan yarığa doğru boşalır, kökenine—ilksel uçuruma—geri akar."
  },
  AvgDialog_65471_Content_15 = {
    Text = "Bükülmüş ışık Karanlık’ın içinden sıçrar; ifadesiz bir yüzden farksız, sessizce bu güçsüz ruhları seyreder."
  },
  AvgDialog_65471_Content_16 = {
    Text = "Kapının önünde, \"Doll\"ın bedeninin bir parçası yarığa yenik düşer, ama o aldırmaz. Yüzlerindeki ifadeleri seyreder, sevinçle sırıtır."
  },
  AvgDialog_65471_Content_17 = {
    Text = "Hâlâ anlamıyor musunuz? Yıkım, siz zavallılar. Yıkım tek gerçek cevaptır."
  },
  AvgDialog_65471_Content_18 = {
    Text = "Evren bir yalandır—aptalın rüyası, bütünüyle anlamsız."
  },
  AvgDialog_65471_Content_19 = {
    Text = "Tüm çaba nafile. Geleceği getirebilecek olan yalnızca yeni bir başlangıçtır."
  },
  AvgDialog_65471_Content_2 = {
    Text = "Hıııh—"
  },
  AvgDialog_65471_Content_20 = {
    Text = "Onu kucakla—"
  },
  AvgDialog_65471_Content_21 = {Text = "@2!—"},
  AvgDialog_65471_Content_22 = {
    Text = "Kapı'nın içinden kaotik sesler yankılanır, sanki bir şey tarafından çağrılmış gibi."
  },
  AvgDialog_65471_Content_23 = {
    Text = "Bebeksi feryatlar, kadim büyüler, saf kötülük. Şuursuz sesler damarlarından taşar, Yıkımın nefesini taşıyarak Kapıdan fışkırır."
  },
  AvgDialog_65471_Content_24 = {Text = "Tawil!"},
  AvgDialog_65471_Content_25 = {
    Text = "Tawil grubun önünde durur, engin kanatlarını açarken çok boyutlu tonlar gitgide daha da solar."
  },
  AvgDialog_65471_Content_26 = {
    Text = "Yarık, kontrolden çıkmış halde genişler, Onların aklının son kırıntılarını da yutar."
  },
  AvgDialog_65471_Content_27 = {
    Text = "Ramona, {Male=onu,Female=onu} hissedebiliyor musun?"
  },
  AvgDialog_65471_Content_28 = {
    Text = "Ben... yapamıyorum...\nKapı'ya girdikten sonra, {Male=his,Female=her} bağlantısı öylece kayboldu..."
  },
  AvgDialog_65471_Content_29 = {
    Text = "Ramona doğrulur, kılıç elinde."
  },
  AvgDialog_65471_Content_3 = {
    Text = "Tawil? Sen..."
  },
  AvgDialog_65471_Content_30 = {
    Text = "{Male=O,Female=O} dönene kadar, {Male=onun,Female=onun} için hattı ben tutacağım..."
  },
  AvgDialog_65471_Content_31 = {
    Text = "Geri çekil."
  },
  AvgDialog_65471_Content_32 = {Text = "!!!"},
  AvgDialog_65471_Content_33 = {
    Text = "Ramona tam Tawil’e doğru atılmaya hazırlanırken, görünmez bir el onu geri çeker."
  },
  AvgDialog_65471_Content_34 = {
    Text = "Yarık... Durdu mu?..."
  },
  AvgDialog_65471_Content_35 = {
    Text = "Hayır, çırpınıyor..."
  },
  AvgDialog_65471_Content_36 = {
    Text = "Tawil yavaşça Gözlerini açar."
  },
  AvgDialog_65471_Content_37 = {
    Text = "Onları yutan o dehşet verici yarık, artık insan algısının ötesindeki frekanslarda titreşiyor."
  },
  AvgDialog_65471_Content_38 = {
    Text = "O dehşet verici ağız, korktuğu iki gücün önünde titreyen bir yaban hayvanı gibi siner."
  },
  AvgDialog_65471_Content_39 = {Text = "Geciktim."},
  AvgDialog_65471_Content_4 = {
    Text = "Sagacity Çağı’nın Gücü tükendi... O, geri döndü."
  },
  AvgDialog_65471_Content_40 = {
    Text = "Devasa Gözbebeksiz Göz’ün altında, ince bir siluet Kapı’nın önünde duruyor."
  },
  AvgDialog_65471_Content_41 = {
    Text = "Koruyucu... Bu, Koruyucu!"
  },
  AvgDialog_65471_Content_42 = {Text = "%player%!"},
  AvgDialog_65471_Content_43 = {Text = "Sonunda..."},
  AvgDialog_65471_Content_44 = {
    Text = "Ramona sana yaklaşır. Elini sallarsın ve o görünmez eller yolunu bir kez daha keser."
  },
  AvgDialog_65471_Content_45 = {
    Text = "Bakışları seni yok edecek.\nBuradan ayrıl."
  },
  AvgDialog_65471_Content_46 = {
    Text = "Gitmek mi? Ne... Ne diyorsun?"
  },
  AvgDialog_65471_Content_47 = {
    Text = "Biz senin Uyandıranların... Birlikte, biz..."
  },
  AvgDialog_65471_Content_48 = {
    Text = "Ramona yeniden Kapı'ya doğru atılmaya hazırlanırken, arkasında Alistair'in sesi yankılanır."
  },
  AvgDialog_65471_Content_49 = {
    Text = "Artık Uyanışçılara ihtiyacı yok, Ramona."
  },
  AvgDialog_65471_Content_5 = {
    Text = "Tawil’in bedeni hafifçe titrer. Ramona’nın desteğiyle, Başlarını güçsüzce kaldırırlar."
  },
  AvgDialog_65471_Content_50 = {
    Text = "Sen... Ne dedin?"
  },
  AvgDialog_65471_Content_51 = {
    Text = "Alistair’ın yanıtını beklemeden Ramona gözlerini kapatır, sana uzanan bağını takip eder."
  },
  AvgDialog_65471_Content_52 = {Text = "!!!"},
  AvgDialog_65471_Content_53 = {
    Text = "Bağlantı... Kayboldu..."
  },
  AvgDialog_65471_Content_54 = {
    Text = "Neden bahsediyorsun, Ramona? Bağ, Koruyucu’yla aramızdaki en güçlü bağımız—nasıl olur da..."
  },
  AvgDialog_65471_Content_55 = {Text = "!!!..."},
  AvgDialog_65471_Content_56 = {
    Text = "Her Uyandırma sahibi gözlerini kapatır, Ruh Alanı’nı yoklar."
  },
  AvgDialog_65471_Content_57 = {
    Text = "Ama ne kadar çabalarlarsa çabalasınlar, hep orada olan, ruh alanlarını yönlendiren o siluet tamamen yok olmuştur."
  },
  AvgDialog_65471_Content_58 = {
    Text = "O kişi tam önlerinde durmaktadır; görünüşü değişmemiştir, ama onların gözünde bu figür bütünüyle yabancıya dönüşür."
  },
  AvgDialog_65471_Content_59 = {
    Text = "Şu an {Male=onun,Female=onun} bağlandığı şey, bizlerin gölgeleri; {Male=kendi,Female=kendi} Otoritesi ve Anılarıyla yeniden yaratılmış varlıklar."
  },
  AvgDialog_65471_Content_6 = {
    Text = "Kapı’nın içindeki kaotik renklerin ortasında, o göz Tawil’in ördüğü aldatmacaları deler ve bir kez daha Herkes’in üzerine iner."
  },
  AvgDialog_65471_Content_60 = {
    Text = "{Male=O,Female=O}... bizimle olan bağı kopardı."
  },
  AvgDialog_65471_Content_61 = {Text = "?!!"},
  AvgDialog_65471_Content_62 = {
    Text = "Neden? Lily... Lily yardım edebilir..."
  },
  AvgDialog_65471_Content_63 = {
    Text = "Tawil başını kaldırır, Kapının içindeki o yalnız siluete bakar."
  },
  AvgDialog_65471_Content_64 = {
    Text = "{Male=O,Female=O}, Tohuwabohu’nun bir Parçası, Yüce İrade’nin bir vekilidir. {Male=Onun,Female=Onun} Ruh Alanı, sonsuz kaos, ilksel delilik barındırır..."
  },
  AvgDialog_65471_Content_65 = {
    Text = "Şimdi {Male=onunla,Female=onunla} bağ kurmak bizi deliliğe sürükler."
  },
  AvgDialog_65471_Content_66 = {
    Text = "{Male=O,Female=O} haklı. Artık {Male=O,Female=O}’nun bize ihtiyacı yok."
  },
  AvgDialog_65471_Content_67 = {
    Text = "Çözünme’nin harap ettiği kanatlarını katlarlar, Uyanış getirenlerin yüzlerini açığa vururlar."
  },
  AvgDialog_65471_Content_68 = {
    Text = "Başardın, Koruyucu... Yoksa artık sana Gözbebeksiz Göz mü demeliyim?"
  },
  AvgDialog_65471_Content_69 = {
    Text = "Sesleri kulaklarına erişir. Uyanış getirenlerin kederli bakışlarını hissedersin. Eskiden olduğu gibi, tanıdık Çağrı’nı beklediklerini bilirsin."
  },
  AvgDialog_65471_Content_7 = {Text = "@2..."},
  AvgDialog_65471_Content_70 = {
    Text = "Gülümsersin. Artık açıklamaya gerek yok."
  },
  AvgDialog_65471_Content_71 = {
    Text = "Dünyanızda yalnızca yaratıcının devasa gözü var karşınızda. Yanınızda kimse yok."
  },
  AvgDialog_65471_Content_72 = {
    Text = "Anım Mythag’da başlar. Onlar, onun her yerindedir."
  },
  AvgDialog_65471_Content_73 = {
    Text = "Beni sayısız kez korudular. Şimdi onları koruma sırası bende."
  },
  AvgDialog_65471_Content_74 = {
    Text = "Devasa gözbebeği merakla büyür, sana bir Bebek, canlı bir oyuncağı keşfederken bakar gibi dikkatle bakar."
  },
  AvgDialog_65471_Content_75 = {
    Text = "Derin bir nefes alır ve başını kaldırırsın. Yüce İrade’nin bakışıyla karşılaşırsın."
  },
  AvgDialog_65471_Content_76 = {
    Text = "Ben, kaybolmuş Parçanım; ve şimdi, bu Parça gözünü hedef alıyor."
  },
  AvgDialog_65471_Content_77 = {
    Text = "Yaratıcının bile İmha Etmeye hakkı yok. Bırak kaos kaosa dönsün. Ölümlü dünya, ölümlülerin dünyası olarak kalsın."
  },
  AvgDialog_65471_Content_78 = {
    Text = "Senin Rüyanı paramparça etmek için önce beni geçmen gerekecek. Yüce İrade, aptal yaratıcı—Tohuwabohu."
  },
  AvgDialog_65471_Content_8 = {
    Text = "Alçak flüt ezgileri yeniden yankılanırken, bir zamanlar sakin olan Kara Havuz şiddetle dalgalanır."
  },
  AvgDialog_65471_Content_9 = {
    Text = "Tawil’in İlahi’si kırılgan bir Bariyer oluşturur; bu ezici Güç karşısında ufalanıp dağılır."
  },
  AvgDialog_65472_Content_1 = {
    Text = "Belirleyici: İlksel Gölge"
  },
  AvgDialog_65472_Content_10 = {
    Text = "Thais... Özür dilerim, ben..."
  },
  AvgDialog_65472_Content_11 = {
    Text = "Tsk tsk tsk. Bana karşı atıp tutarken bu kadar bezgin görünmüyordun, sahtekâr."
  },
  AvgDialog_65472_Content_12 = {
    Text = "Başarısız oldun, Gözbebeği Olmayan Göz’ün parçası. Hem de bütünüyle."
  },
  AvgDialog_65472_Content_13 = {
    Text = "Haklısın, N... Başarısız oldum. Onu yenemem..."
  },
  AvgDialog_65472_Content_14 = {
    Text = "Sıradan bir Parça, gerçek Yaratıcı karşısında hiçbir şey yapamaz..."
  },
  AvgDialog_65472_Content_15 = {
    Text = "Üzgünüm, hepinizi hayal kırıklığına uğrattım..."
  },
  AvgDialog_65472_Content_16 = {
    Text = "Hayal kırıklığı mı? Hayır, heyecan içindeyim, %player%. Bu had safhada taşan gösteri büyüleyici oldu."
  },
  AvgDialog_65472_Content_17 = {
    Text = "Elinden gelen her şeyi yaptın, %player%. Beni hiç hayal kırıklığına uğratmadın."
  },
  AvgDialog_65472_Content_18 = {
    Text = "Ve... Senin savaşın henüz bitmedi."
  },
  AvgDialog_65472_Content_19 = {
    Text = "Thais, gözlerinde yumuşak bir gülümsemeyle başını okşar."
  },
  AvgDialog_65472_Content_2 = {Text = "Ko..."},
  AvgDialog_65472_Content_20 = {
    Text = "Bu... bitmedi mi?"
  },
  AvgDialog_65472_Content_21 = {
    Text = "Sayısız başarısızlığın ortasında, zafere giden bir yolun gölgesini gördüm."
  },
  AvgDialog_65472_Content_22 = {
    Text = "Bir yol... bununla özdeş."
  },
  AvgDialog_65472_Content_23 = {
    Text = "Gözlerini kaparsın. Hikmet Çağı'nın Otoritesi içinde Dalgalanma yaratır. Tawil'in hudutsuz düşünceleri zihnini doldurur. Zahmetsizce, Onların Gözleri'nde Fitil Yolu'nu görürsün."
  },
  AvgDialog_65472_Content_24 = {
    Text = "Gözlerin birden açılır, çevrendeki boşluğu tararsın."
  },
  AvgDialog_65472_Content_25 = {
    Text = "Kapıların Ötesinde, Gölge ve ışık fizik kanunlarına meydan okur, Boyutların sınırlarında hafifçe Titreşim hâlinde yanıp söner."
  },
  AvgDialog_65472_Content_26 = {
    Text = "Bunlar... boyutların sınırları... Aralarındaki bariyerleri mi açtın?"
  },
  AvgDialog_65472_Content_27 = {
    Text = "Bu sayısız boyutun her birinde, senin ve benim sayısız versiyonumuz var. Sayısız Koruyucu, sayısız Tawil, aynı düşmanla yüzleşiyor."
  },
  AvgDialog_65472_Content_28 = {
    Text = "Kapı bunların hepsini birbirine bağlıyor... Ve şimdi, tamamen açık."
  },
  AvgDialog_65472_Content_29 = {
    Text = "Artık anlıyorum, Tawil!"
  },
  AvgDialog_65472_Content_3 = {
    Text = "Koruyucu..."
  },
  AvgDialog_65472_Content_30 = {
    Text = "Bu sayısız boyutta Tohuwabohu eşsiz, ama... biz değiliz."
  },
  AvgDialog_65472_Content_31 = {
    Text = "Doğrulursun, o devasa varlığın bakışıyla yüzleşirsin."
  },
  AvgDialog_65472_Content_32 = {
    Text = "Bakın—sahtekâr dostumuz yine {Male=onun,Female=onun} düşüncesizce hamlesine başlamak üzere."
  },
  AvgDialog_65472_Content_33 = {
    Text = "Haklısın, N... Tek bir Parça hiçbir şey yapamaz."
  },
  AvgDialog_65472_Content_34 = {
    Text = "Ama çökmekte olan Yaratıcı Tanrı’nın düşkün parçaları... yalnızca bir tane değiller..."
  },
  AvgDialog_65472_Content_35 = {
    Text = "Kapının içindeki boşluğu tararsın. Sayısız Göz, sayısız Boyuttan sana bakar."
  },
  AvgDialog_65472_Content_36 = {
    Text = "Yine de bilirsin—sana bakmadığını."
  },
  AvgDialog_65472_Content_37 = {
    Text = "O bilinmeyen Boyutlarda, sayısız versiyonun Yaratıcı'nın Gözleri'yle buluşur."
  },
  AvgDialog_65472_Content_38 = {
    Text = "Boyutsal sınırları bütünüyle yırt, Tawil."
  },
  AvgDialog_65472_Content_39 = {
    Text = "Tawil usulca başını sallar ve Ellerini kaldırır."
  },
  AvgDialog_65472_Content_4 = {
    Text = "Sen... Tawil misin?"
  },
  AvgDialog_65472_Content_40 = {
    Text = "İnce bir zar yırtılmış gibi, o sayısız göz, görüş alanında berraklaşıyor."
  },
  AvgDialog_65472_Content_41 = {
    Text = "Zarın yırtıldığı anda, sayısız ses kulaklarına hücum eder."
  },
  AvgDialog_65472_Content_42 = {
    Text = "Hayatımı bir kez zaten kaybettim. Tek bir seçimim var: Bana ait olanı koruyarak ölmek ya da onu terk ederek hayatta kalmak."
  },
  AvgDialog_65472_Content_43 = {
    Text = "\"Yapabilirim. Her ne felaketse bu, O'nun Varışını durduracağım!\""
  },
  AvgDialog_65472_Content_44 = {
    Text = "\"Seni oradan çıkaracağım! ...Ramona, beni bekle!!\""
  },
  AvgDialog_65472_Content_45 = {
    Text = "\"Uyandıranlar—temasa geçin!\""
  },
  AvgDialog_65472_Content_46 = {Text = "..."},
  AvgDialog_65472_Content_47 = {
    Text = "Erkek sesleri. Kadın sesleri. Tutkulu sesler. Ağıt yüklü sesler."
  },
  AvgDialog_65472_Content_48 = {
    Text = "Bu sesler tanıdık ama yabancıdır; ilk kez aynada kendi yüzünü gören bir bebek gibidirler."
  },
  AvgDialog_65472_Content_49 = {
    Text = "Ve o yansıyan bebek artık seni de görüyor."
  },
  AvgDialog_65472_Content_5 = {
    Text = "Ben Tawil'im ve içindeki Hikmet Çağı'nın Otoritesi'yim.\nGüvendesin, Koruyucu."
  },
  AvgDialog_65472_Content_50 = {
    Text = "Bunlar benim seslerim"
  },
  AvgDialog_65472_Content_51 = {
    Text = "Duyuyorum... Bunlar benim seslerim."
  },
  AvgDialog_65472_Content_52 = {
    Text = "Muhteşem, muhteşem... Ben bile sahnede sana katılmaktan kendimi alamıyorum."
  },
  AvgDialog_65472_Content_53 = {
    Text = "Devam edin, sahneye çıkmaya devam edin. Bakalım siz parçalar neler yapabiliyorsunuz!"
  },
  AvgDialog_65472_Content_54 = {
    Text = "Git, Koruyucu... Sana inanmayı seçtim. Hangi kararı verirsen ver, sana yardım edeceğim."
  },
  AvgDialog_65472_Content_55 = {
    Text = "Tawil, Thais, N... Üç Eon'un Gücü sana doğru dalgalanır.\nSen ayağa kalkar, Gümüş Anahtar'ı havaya kaldırırsın."
  },
  AvgDialog_65472_Content_56 = {
    Text = "Alaca bir mekân açılır; Tohuwabohu’nun gözleri belirirken tanıdık sahneler belirmeğe başlar. Sayısız çöken boyutta, sayısız gümüş ışık aynı anda tutuşur."
  },
  AvgDialog_65472_Content_57 = {
    Text = "Gümüş ışıklar Londinium’un balmumu müzesini, Rye’ın sanatoryumunu, Bridgeport’un denizlerini, Remouahe’nin kumlarını aydınlatıyor. Geçmişini, tüm sınavlarını ve büyümeni ışığa boğuyorlar."
  },
  AvgDialog_65472_Content_58 = {
    Text = "O kırılgan, önemsiz parçalar şimdi bıçaklarını Yaratıcı Tanrı’ya doğrultuyor."
  },
  AvgDialog_65472_Content_59 = {
    Text = "Bir göz, bir yara, bir çizik—hatta hiçbir şey... Hiç fark etmez."
  },
  AvgDialog_65472_Content_6 = {Text = "Burası..."},
  AvgDialog_65472_Content_60 = {
    Text = "Bak, Tohuwabohu. Biz senin Parçalarınız, biz Mythag'ın Sır Koruyucuları'yız..."
  },
  AvgDialog_65472_Content_61 = {
    Text = "Bedeli ne olursa olsun, seni burada tutacağız!"
  },
  AvgDialog_65472_Content_7 = {
    Text = "Hikmet Çağı zamanı kısaca geri sardı; hâlâ Kapının içindeyiz."
  },
  AvgDialog_65472_Content_8 = {
    Text = "Tohuwabohu geçmişine göz attı. Ayak bastığın her yerde gözler açıyor. Londinium, Rye, Remouahe..."
  },
  AvgDialog_65472_Content_9 = {
    Text = "O'nun bakışı hâlâ peşimizde."
  },
  AvgDialog_65473_Content_1 = {
    Text = "Yansıtma’larımda, bu kadar ileri gideceğini hiç öngörmemiştim."
  },
  AvgDialog_65473_Content_2 = {
    Text = "Sahip olduklarını bırakmak kolay değildir."
  },
  AvgDialog_65473_Content_3 = {
    Text = "Tereddüt ediyorsun. Bu normal. Tereddüt, insanlığın en yozlaşmış—ve yine de en parlak—parçasıdır."
  },
  AvgDialog_65473_Content_4 = {
    Text = "Ama işte buradasın. Artık tereddüt etme lüksün yok, %player%."
  },
  AvgDialog_65473_Content_5 = {
    Text = "Bir tanrıya ancak bir tanrı karşı koyabilir. İnsana dair her şey senden soyulacak."
  },
  AvgDialog_65473_Content_6 = {
    Text = "Söyle bana—hazır mısın?"
  },
  AvgDialog_65473_Content_7 = {
    Text = "Hazırım, Profesör Doll."
  },
  AvgDialog_65473_Content_8 = {
    Text = "Bu Yol’un sonunda seni bekliyor."
  },
  AvgDialog_65473_Content_9 = {
    Text = "Benimle olan Bağlantı’nı kopar, sonra cesurca onunla yüzleş."
  },
  AvgDialog_65474_Content_1 = {
    Text = "Efendim, siz gerçekten... bizi terk mi ediyorsunuz?"
  },
  AvgDialog_65474_Content_2 = {
    Text = "Affedin beni, efendim... Bunu söylememeliydim."
  },
  AvgDialog_65474_Content_3 = {
    Text = "Anlıyorum—bunu bizi korumak için yapıyorsun... Ama ben sonsuza dek senin kalkanın olacağıma yemin ettim."
  },
  AvgDialog_65474_Content_4 = {
    Text = "Efendim, eğer kararınız kesinse... lütfen beni sadakat yeminimden azat edin."
  },
  AvgDialog_65474_Content_5 = {
    Text = "Ben... kararımı verdim, Ogier."
  },
  AvgDialog_65474_Content_6 = {
    Text = "Sen de tıpkı benim gibi bir savunucusun, efendim."
  },
  AvgDialog_65474_Content_7 = {
    Text = "Beni kendi elinle serbest bıraktıktan sonra, arkanda Uzaklardan nöbet tutacağım."
  },
  AvgDialog_65474_Content_8 = {
    Text = "Tanıklık edeceğim ve adaletini tanrılara ilan edeceğim!"
  },
  AvgDialog_65475_Content_1 = {
    Text = "Her şeyi koparmak, jilet keskinliğinde bir Bıçak, muazzam bir Güç ve her şeyden öte, boyun eğmeyen bir yürek ister."
  },
  AvgDialog_65475_Content_2 = {
    Text = "Bütün bunlarla hazır mısın?"
  },
  AvgDialog_65475_Content_3 = {
    Text = "Be... hazırım..."
  },
  AvgDialog_65475_Content_4 = {
    Text = "Vazgeçmek kolay değil. Senin Cevabın’a saygı duyuyorum."
  },
  AvgDialog_65475_Content_5 = {
    Text = "Kılıcını çek, %player%."
  },
  AvgDialog_65475_Content_6 = {
    Text = "Son kılıç ustalığı dersin şimdi başlıyor—"
  },
  AvgDialog_65476_Content_1 = {
    Text = "Hıııh—"
  },
  AvgDialog_65476_Content_10 = {
    Text = "Kapı’ya doğru bakar, kaşlarını sıkıca çatar."
  },
  AvgDialog_65476_Content_11 = {
    Text = "Koruyucu! Oradan çık!!"
  },
  AvgDialog_65476_Content_12 = {
    Text = "Dışarıdan gelen sesler sana boğuk bir uğultu halinde ulaşır. Göğsünü tutar, başını kaldırırsın."
  },
  AvgDialog_65476_Content_13 = {
    Text = "Gözler. Sayısız göz. Tüm gücünle birini parçaladıktan sonra, sayısız göz mahmurca açılır; sana Kapı’nın içinden, evrenin her Boyutundan bakar."
  },
  AvgDialog_65476_Content_14 = {
    Text = "O şiddetli sarsıntı bilincini paramparça ediyor, anılarını bulandırıyor. Zihnindeki kaosun içinde N'in sözleri canlı bir şekilde gözlerinin önünde beliriyor. Kendi kendine alaycı bir gülümseme atıyorsun."
  },
  AvgDialog_65476_Content_15 = {
    Text = "Haklıydın, N... Gerçekte neyle yüzleştiğim hakkında hiçbir fikrim yokmuş..."
  },
  AvgDialog_65476_Content_16 = {
    Text = "Ben sadece bir Parçayım... O’nun Bakışı’yla yüzleşmeye asla layık değildim..."
  },
  AvgDialog_65476_Content_17 = {
    Text = "Kendini zorlayarak doğrulursun, o sayısız aptal Göz Bebeğiyle yüzleşirsin."
  },
  AvgDialog_65476_Content_18 = {
    Text = "Öfke ve Ağıt içinde kaynar. Ama hiçbir şeyi değiştiremeyeceğini bilirsin."
  },
  AvgDialog_65476_Content_19 = {Text = "@2...@3..."},
  AvgDialog_65476_Content_2 = {
    Text = "Tüm saldırılar boşlukta yok olur; tüm savunmalar zahmetsizce tuzla buz olur."
  },
  AvgDialog_65476_Content_20 = {
    Text = "Sayısız bakış sana dikiliyor. Çözünme bir gelgit gibi üzerine çullanıyor. İçindeki Otoriteler Çözünme'ye karşı koyuyor, ama onun ezici hızına yetişemiyor."
  },
  AvgDialog_65476_Content_21 = {
    Text = "Dayanılmaz acı bedenini kasıp kavuruyor, titriyorsun. Anılar Çözünme içinde eriyor; zihnin boşalıyor. Mekanik bir şekilde Gümüş Anahtar'ı kavrayıp o titreyen bakışa doğru kaldırıyorsun—"
  },
  AvgDialog_65476_Content_22 = {Text = "@3!"},
  AvgDialog_65476_Content_23 = {
    Text = "Gümbür—"
  },
  AvgDialog_65476_Content_24 = {
    Text = "Gümbür—"
  },
  AvgDialog_65476_Content_25 = {
    Text = "Koruyucu!—"
  },
  AvgDialog_65476_Content_3 = {
    Text = "Kapı’nın alanında şiddetli şok dalgaları patlar; dizlerinin üzerine çökersin, zonklayan kalbini acı içinde kavrarsın."
  },
  AvgDialog_65476_Content_4 = {
    Text = "Bu... Ne oluyor!?! {Male=O,Female=O} açıkça kazanmıştı..."
  },
  AvgDialog_65476_Content_5 = {
    Text = "{Male=O,Female=O} kazanmadı, Ramona."
  },
  AvgDialog_65476_Content_6 = {
    Text = "{Male=Onun,Female=Onun} yendiği şey, Tohuwabohu’nun yalnızca bir bakışıydı."
  },
  AvgDialog_65476_Content_7 = {
    Text = "...Bir bakış mı?"
  },
  AvgDialog_65476_Content_8 = {
    Text = "Tohuwabohu sayısız Boyut boyunca var olur. Gözlerini açtığında, O'nun Bakışları hesapsız Diyarları tarar."
  },
  AvgDialog_65476_Content_9 = {
    Text = "Bu engellenen bakış, Tohuwabohu’nun dikkatini çekti. Diğer bakışlar—gerçekten Güçlü olanlar..."
  },
  AvgDialog_65477_Content_1 = {
    Text = "Yol’un sonunda duruyor, sana bakıyor."
  },
  AvgDialog_65477_Content_10 = {
    Text = "Düşmemem gerektiğini söylemiştin. Ben biricik Koruyucu'yum—Çözünme'ye kaybolan tarihi araştırmalı ve belgele-meliyim..."
  },
  AvgDialog_65477_Content_11 = {
    Text = "Başardın. Elde ettiğin—ve bundan sonra elde edeceğin—şeyler, bunun çok ötesine geçiyor."
  },
  AvgDialog_65477_Content_12 = {
    Text = "Kendimi çok yıpranmış hissediyorum, Ramona."
  },
  AvgDialog_65477_Content_13 = {
    Text = "Biliyorum, Koruyucu."
  },
  AvgDialog_65477_Content_14 = {
    Text = "Ben senin Destekçin ve ortağınım. Her şey boyunca yanında oldum; her Savaş’a tanıklık ettim, söylediğin her kelimeyi duydum..."
  },
  AvgDialog_65477_Content_15 = {
    Text = "Bu yolculuğun seni tükettiğini biliyorum, özellikle de bugün... tam şu anda..."
  },
  AvgDialog_65477_Content_16 = {
    Text = "Parıldayan yaşlar Onun Gözleri’nden süzülüyor. Gülümsüyor, Bakış’ını seninkine kilitliyor."
  },
  AvgDialog_65477_Content_17 = {
    Text = "Bu, son Seçim. Basit—tıpkı sana öğrettiğim o sorular gibi, tıpkı ilk Bağlantı’mız gibi..."
  },
  AvgDialog_65477_Content_18 = {
    Text = "Benimle olan Bağlantı’yı kopar, Koruyucu."
  },
  AvgDialog_65477_Content_19 = {Text = "..."},
  AvgDialog_65477_Content_2 = {
    Text = "O Akut'ta Bahar’da gözlerini ilk açtığında, yüzüne düşen dağınık saç tellerini hatırlıyorsun."
  },
  AvgDialog_65477_Content_20 = {
    Text = "Ramona ile olan Bağlantı’yı kopar"
  },
  AvgDialog_65477_Content_21 = {
    Text = "Bir keresinde, hesabın da basit olduğunu söylemiştin. Beni iki kez kandırdın, Ramona."
  },
  AvgDialog_65477_Content_22 = {
    Text = "Bu problem kalkülüsten çok daha Zor."
  },
  AvgDialog_65477_Content_23 = {
    Text = "Özür dilerim... bu sefer kopyalayacak bir cevap yok...\nBu yalnızca senin. Çözebileceğine inanıyorum."
  },
  AvgDialog_65477_Content_24 = {
    Text = "...Elveda, Koruyucu."
  },
  AvgDialog_65477_Content_3 = {
    Text = "Mythag’daki çalışmaların sırasında onun çatılmış kaşlarını hatırlıyorsun."
  },
  AvgDialog_65477_Content_4 = {
    Text = "Onun El’ini ilk tuttuğunda aranızda dolaşan o ince akımı hatırlıyorsun."
  },
  AvgDialog_65477_Content_5 = {
    Text = "Akım eldivenleri, parmak uçlarını, sinirleri delip geçti ve zihninin derinliklerinde ilk net silüete dönüştü.\nO silüetle birlikte yürüdüğün uzun, çetin yolu hatırlıyorsun."
  },
  AvgDialog_65477_Content_6 = {
    Text = "Şimdi, yeniden o siluetin önünde duruyorsun; elinde, kopuşun maddesiz Bıçak’ını sıkıca kavramış halde."
  },
  AvgDialog_65477_Content_7 = {
    Text = "Anahtar Mezarı Töreni’ndeki ilk Bağlantı’mız sırasında söylediklerimi hatırlıyor musun, Koruyucu?"
  },
  AvgDialog_65477_Content_8 = {
    Text = "Hatırlıyorum. Her kelimesini."
  },
  AvgDialog_65477_Content_9 = {
    Text = "Bir yıl öncesinden beri o günü beklediğini söylemiştin. Ruhani Bağlantı’mızın inanılmaz derecede kararlı olduğunu—ruhlarımızın ve Canlılık’ımızın hiç bu kadar Güçlü olmadığını."
  },
  AvgDialog_65478_Content_1 = {
    Text = "Fenerin imha edildi, \"Doll\"!"
  },
  AvgDialog_65478_Content_10 = {Text = "@2..."},
  AvgDialog_65478_Content_11 = {
    Text = "Bu... Hayır!..."
  },
  AvgDialog_65478_Content_12 = {
    Text = "Bu... Hayır!..."
  },
  AvgDialog_65478_Content_13 = {
    Text = "Kavitasyon, sıvılaşma, toz hâline getirme, silip yok etme. Çözünme’nin ilerleyişini ezbere biliyorsun."
  },
  AvgDialog_65478_Content_14 = {
    Text = "Ama bu Bakış’ın altında, Çözünme’ye dair bütün Bilgin çöker."
  },
  AvgDialog_65478_Content_15 = {
    Text = "Duvarlar yok olur. Basamaklar yok olur. Hatta Kara Havuz’un kendisi bile yok olur."
  },
  AvgDialog_65478_Content_16 = {
    Text = "Duvarların rengini unutursun. Basamakların yerini unutursun. O Bakış’ın altında, her şey ebedî hiçliğe çözünür; geride, hatta boşluk fikri bile kalmaz."
  },
  AvgDialog_65478_Content_17 = {
    Text = "Bakış etrafı süpürür, sonra sonunda sana kilitlenir."
  },
  AvgDialog_65478_Content_18 = {Text = "!!!"},
  AvgDialog_65478_Content_2 = {
    Text = "Juliette gerçeği gördü—bu, senin istediğin gelecek değil..."
  },
  AvgDialog_65478_Content_20 = {
    Text = "Gözlerini aç, Koruyucu."
  },
  AvgDialog_65478_Content_21 = {
    Text = "Işık hiç yakmıyor—tam tersine, görüş alanını dolduran bir yığın gümüş-beyaz Kanat gibi yumuşak geliyor."
  },
  AvgDialog_65478_Content_22 = {
    Text = "Tawil'in yüzünü görüyorsun.\nİlk tanıştığınız günkü gibi: kutsal, yumuşak, dokunulmaz."
  },
  AvgDialog_65478_Content_23 = {
    Text = "Altı Kanatları açılır, seni her şeyi yok eden Bakış’tan korurlar. Aşkın kutsal ışık arkada titreşir; her kanat çırpışı, Boyutların yer değiştirmesidir ve her şeyi imha eden Bakış’ı var olmayan bir tekilliğe saptırır."
  },
  AvgDialog_65478_Content_24 = {
    Text = "Siyah sıvılar Kanatları boyunca damlar, dokunulmaz ilahi etin her kıvrımını pençeler. Her gelip geçen anda, Bedenleri çıplak kemiklere kadar solup gider, Çözünme yüzlerini tekrar tekrar sıvıya çevirir—yalnızca yeniden birbirine örülmek için."
  },
  AvgDialog_65478_Content_25 = {
    Text = "—Bakış’a Boyutlarla karşı koyar, her şeyi silen o karşı konulamaz iradeye meydan okurlar."
  },
  AvgDialog_65478_Content_26 = {
    Text = "Bu saflık ve pislik savaşında, her saniye sayısız kez çarpışırlar. Her çarpışma, Tawil’in yüzünden bir parça daha Ana Renk’i süzer alır."
  },
  AvgDialog_65478_Content_27 = {
    Text = "Şimdilik, O'nun Bakışı saklandığım boyutta oyalanacak. Hâlâ zamanın var, Koruyucu."
  },
  AvgDialog_65478_Content_28 = {
    Text = "Tawil, sen...!"
  },
  AvgDialog_65478_Content_29 = {
    Text = "Dinle, Koruyucu."
  },
  AvgDialog_65478_Content_3 = {
    Text = "Gelecek mi? Ben o saf aptal Juliette gibi değilim. Benim hep istediğim şey... asla bir “gelecek” olmadı."
  },
  AvgDialog_65478_Content_30 = {
    Text = "Kapıdan geç. Cevapları bul. Kendinle ilgili her şeyi hatırla."
  },
  AvgDialog_65478_Content_31 = {
    Text = "Onlar seni süzüyor. O yumuşak, kutsal yüz, sarsılmaz bir otorite taşıyor."
  },
  AvgDialog_65478_Content_32 = {
    Text = "Bizi yendin. Başardın."
  },
  AvgDialog_65478_Content_33 = {
    Text = "Şimdi, git ve onları kurtar."
  },
  AvgDialog_65478_Content_34 = {
    Text = "Yine yapacaksın. Değil mi, Koruyucu?"
  },
  AvgDialog_65478_Content_4 = {
    Text = "Ayaklarının dibindeki zemini parçalar ve bulanık sıvılar kaplamış, kan ve koyu kıvamlı D-balçık bedenine sıçramış. Aldırmaksızın başını geriye atıyor ve narin bedenini bütünüyle yalanlayan çılgın bir kahkaha patlatıyor."
  },
  AvgDialog_65478_Content_5 = {
    Text = "Artık çok geç, aptal insanlar."
  },
  AvgDialog_65478_Content_6 = {
    Text = "Artık bu savaşın sonucu hiçbir şey ifade etmiyor...\nSon Kazanan benim, Koruyucu."
  },
  AvgDialog_65478_Content_7 = {Text = "!!!"},
  AvgDialog_65478_Content_8 = {
    Text = "\"Doll\" memnun bir gülümseme takınır; elleri, çürümeye adanmış dindar bir buket gibi hafifçe açıktır."
  },
  AvgDialog_65478_Content_9 = {
    Text = "Yavaşça diz çöker ve arkasında, devasa Kapı tamamen aralanmış hâlde durur."
  },
  AvgDialog_65479_Content_1 = {Text = "Rehber"},
  AvgDialog_65479_Content_10 = {Text = "Uyanış."},
  AvgDialog_65479_Content_11 = {Text = "@4!..."},
  AvgDialog_65479_Content_12 = {
    Text = "İkiz heykeller çoktan paramparça oldu... Ama neden..."
  },
  AvgDialog_65479_Content_13 = {
    Text = "Ruh Alanı’nda sayısız dalga kıpırdanıyor. Dünyanın dört bir yanından gelen şok dalgaları, kristal bir berraklıkla zihnini dolduruyor."
  },
  AvgDialog_65479_Content_14 = {
    Text = "Bu... bir D-yarık!..."
  },
  AvgDialog_65479_Content_15 = {
    Text = "Balmumu Müzesi’nin yapışkan cehennemine tanık oldun, Rye’ın grotesk uçurumuna baktın ve az önce Kara Havuz’un dehşet verici titremelerine tahammül ettin."
  },
  AvgDialog_65479_Content_16 = {
    Text = "Çözünme üzerine kayda geçmiş tüm insan Bilgi’sini biliyorsun, ama hiçbir kayıt, D-yarık’ların uğursuz siyah çiçekler gibi açıp dünyanın her köşesinde aynı anda patlayabileceği konusunda seni uyarmadı."
  },
  AvgDialog_65479_Content_17 = {
    Text = "Sayısız yüzyıl boyunca, sayısız medeniyet boyunca insanlık durmaksızın keşfetti; hayatlarını ve tutkularını feda etti.\nAma gerçek kaosun karşısında, kazandığımız tek şey kırılganlık ve cehalet."
  },
  AvgDialog_65479_Content_18 = {
    Text = "Tsk tsk tsk, ne büyük bir gösteri...\nYakında uyanacak. Orada öylece bakakalmaya devam edersen, çok geç olacak, Koruyucu."
  },
  AvgDialog_65479_Content_19 = {
    Text = "H... Sen değildin mi?"
  },
  AvgDialog_65479_Content_2 = {
    Text = "Uzun bir rüya gördü."
  },
  AvgDialog_65479_Content_20 = {
    Text = "Ben mi? Ha."
  },
  AvgDialog_65479_Content_21 = {
    Text = "N, elindeki gülü derin bir nefesle içine çeker ve memnun bir iç çekiş bırakır."
  },
  AvgDialog_65479_Content_22 = {
    Text = "İzlemesi bu kadar eğlenceliyken oyunu neden oynayasın ki?"
  },
  AvgDialog_65479_Content_23 = {
    Text = "Mythag'ın köstebeği başka biri..."
  },
  AvgDialog_65479_Content_24 = {
    Text = "Doğru... İkiz heykeller yenildi, demek ki Onu uyandıran o hain.\nDoll bunu araştırıyordu—onu hemen bulmalıyız!"
  },
  AvgDialog_65479_Content_25 = {
    Text = "Broşundaki haberleşme düğmesine hızla basarsın."
  },
  AvgDialog_65479_Content_26 = {
    Text = "Kukla sus pus oldu."
  },
  AvgDialog_65479_Content_27 = {Text = "!!!"},
  AvgDialog_65479_Content_28 = {
    Text = "İletişimcinin boş yankısında, Alistair’ın silueti Kara Havuz’un gölgelerinden belirir."
  },
  AvgDialog_65479_Content_29 = {Text = "Şuna bak."},
  AvgDialog_65479_Content_3 = {
    Text = "Tanrıları ve yıldızları, tozun uygarlıklara hayat verişini ve uygarlıkların tekrar toza çöküşünü düşledi."
  },
  AvgDialog_65479_Content_30 = {
    Text = "Tekerlekli sandalyenin kolunda küçük bir bileşen duruyor."
  },
  AvgDialog_65479_Content_31 = {
    Text = "Kuklanın yapay bedeni"
  },
  AvgDialog_65479_Content_32 = {
    Text = "Bu... Doll'un bedeninden bir parça..."
  },
  AvgDialog_65479_Content_33 = {
    Text = "Vücuduna bir program implant etti. Eğer bir şeyler ters gider ve onu kontrol edemezse, otomatik pilotla bana geri döner."
  },
  AvgDialog_65479_Content_34 = {
    Text = "Doll... Bilincini mi kaybetti?!\nBu o hainin işi olmalı...!"
  },
  AvgDialog_65479_Content_35 = {
    Text = "Alistair ciddi bir ifadeyle başını sallar."
  },
  AvgDialog_65479_Content_36 = {
    Text = "Kukla’nın yapay bedeninde silik bir iz taşıyor. Bu, bize bıraktığı ipucu."
  },
  AvgDialog_65479_Content_37 = {
    Text = "O izin nereye götürdüğünü hissettim.\nTam burada, Kara Havuz'da."
  },
  AvgDialog_65479_Content_38 = {
    Text = "Tohuwabohu’yu uyandırıyor... Onu çabuk bulmalıyız!"
  },
  AvgDialog_65479_Content_4 = {
    Text = "Nefret ve sevgiyi, sevinç ve dehşeti rüyasında gördü."
  },
  AvgDialog_65479_Content_5 = {
    Text = "Hafif Uykudan sarsılarak uyandı. Rüyadaki hiçbir şey aslında hiç var olmamıştı."
  },
  AvgDialog_65479_Content_6 = {
    Text = "Kadim kaos... kör ahmak tanrı..."
  },
  AvgDialog_65479_Content_7 = {Text = "@2..."},
  AvgDialog_65479_Content_8 = {
    Text = "Evrenin yaratıcısı... evrenin yıkımcısı..."
  },
  AvgDialog_65479_Content_9 = {Text = "@3..."},
  AvgDialog_65480_Content_1 = {
    Text = "İşte orada!"
  },
  AvgDialog_65480_Content_10 = {
    Text = "\"Kukla\", bana bak—kendine gel! Sen asla Yıkım’ı seçen biri olmadın!"
  },
  AvgDialog_65480_Content_11 = {
    Text = "Beyin havuzu yeni kabuğuna bağlanırken, eklemler, sanki yeraltı yaratığı zincirlerine karşı geriniyormuşçasına, ilik donduran bir gıcırtıyla sürtünür."
  },
  AvgDialog_65480_Content_13 = {
    Text = "Güler; sesi, sessiz mekânda yankılanırken soğuk bir bıçak gibi tenini tırmalar, ona karşı çıkmaya cüret eden her aptalla alay eder."
  },
  AvgDialog_65480_Content_14 = {
    Text = "Tek yol bu!"
  },
  AvgDialog_65480_Content_15 = {
    Text = "@4’i gördüğüm anda, her olasılığın @2 bir gelecek tarafından yutulduğunu gördüm."
  },
  AvgDialog_65480_Content_16 = {
    Text = "Artık umut, acıyı uzatan bir zehirden ibaret. İnsanlar gerçek huzuru ancak tam, hızlı bir Yok Oluş’ta bulabilir."
  },
  AvgDialog_65480_Content_17 = {
    Text = "Hayır... Bu doğru değil. Daha önce de Aeon Tecessüdlerini yendik—birlikte mucizeler yarattık."
  },
  AvgDialog_65480_Content_18 = {
    Text = "Mucizeler mi?"
  },
  AvgDialog_65480_Content_19 = {
    Text = "\"Kukla\" nın gözlerinde bir anlığına bir mücadele titreşimi çakıyor, fakat onu hızla Delilik yutuyor."
  },
  AvgDialog_65480_Content_2 = {
    Text = "Beklediğimden beş dakika geç kaldın. Beş dakika—pek çok şey halletmek için fazlasıyla yeterli."
  },
  AvgDialog_65480_Content_20 = {
    Text = "Mucizeler gelip geçici düşlerdir. Hiçbir şeyi değiştirmedik."
  },
  AvgDialog_65480_Content_21 = {
    Text = "Neler öğrendiğim hakkında hiçbir fikrin yok! Bunların hepsi—"
  },
  AvgDialog_65480_Content_22 = {
    Text = "Sesi dehşet notalarına bükülüyor, yozlaşmış havada kök salıyor. Dudakları kıpırdıyor, kavrayışı aşan gerçekleri haykırmaya çalışıyor, fakat her hece insan aklını aşıyor."
  },
  AvgDialog_65480_Content_23 = {
    Text = "Bükülme, bükülme—bilinmeyenden yükselen çığlıklar gibi. Korku ve umutsuzluk yoğun bir sis gibi yayılıyor, sessizce odanın her köşesini dolduruyor..."
  },
  AvgDialog_65480_Content_24 = {Text = "..."},
  AvgDialog_65480_Content_25 = {
    Text = "Seni baştan çıkarmak ve saptırmak için elinden gelen her şeyi yapacak. Kendi yargına güvenmen gerekiyor."
  },
  AvgDialog_65480_Content_26 = {
    Text = "Eğitmenine başını sallayıp Kara Havuz’un derinliklerine doğru ilerliyorsun."
  },
  AvgDialog_65480_Content_27 = {
    Text = "\"Doll\" hâlâ bu kabuğun içinde hapsolmuş durumda, arkasında solgun bir ışıkla parıldayan bir mühür dizilimi var."
  },
  AvgDialog_65480_Content_28 = {
    Text = "Dar bir kafese kapatılmış bir canavar gibi, onun gözleri dizginsiz bir delilikle yanıyor."
  },
  AvgDialog_65480_Content_29 = {
    Text = "Demek... Mythag’ın küçük uşak köpeği gelmiş."
  },
  AvgDialog_65480_Content_3 = {
    Text = "“Doll”?!!"
  },
  AvgDialog_65480_Content_30 = {
    Text = "Mührün tabanı, hiçbir ışığın nüfuz etmediği derin bir karanlığa gömülüyor; orada onu yalnızca dipsiz bir sessizlik ve bilinmeyen dehşetler bekliyor."
  },
  AvgDialog_65480_Content_31 = {
    Text = "\"Doll\"、Kapının Ardındaki’nde tam olarak ne gördün... Ugh!"
  },
  AvgDialog_65480_Content_32 = {
    Text = "Bir gölge gibi fırlıyor, saçlarının arkasından kavrayıp yüzünü omzuna çarpıyor."
  },
  AvgDialog_65480_Content_33 = {
    Text = "Acıyla irkiliyorsun, arkandaki refakatlerinden gelen nefes kesilişlerini duyuyorsun, ama odaklanabildiğin tek şey, fazlasıyla yakın, eğlenceyle örülü Doll’un sesi."
  },
  AvgDialog_65480_Content_34 = {
    Text = "Bizim @3 henüz bizi göremiyor..."
  },
  AvgDialog_65480_Content_35 = {Text = "...Ne?"},
  AvgDialog_65480_Content_36 = {
    Text = "Bir kez @3’in bakışı gerçekten indiğinde, her şey sona erecek."
  },
  AvgDialog_65480_Content_37 = {
    Text = "Kıyamet gelmeden önce, her zaman Mythag’ın tasmasını çıkarıp bana katılabilirsin."
  },
  AvgDialog_65480_Content_38 = {
    Text = "Tepkini görmezden geliyor, kulaklarına sevda sözleri fısıldayan bir sevgili gibi, ateşli bir içtenlikle, çılgın davetini mırıldanıyor."
  },
  AvgDialog_65480_Content_39 = {
    Text = "Seni buradan izleyeceğim."
  },
  AvgDialog_65480_Content_4 = {
    Text = "“Doll”... Sen misin?!"
  },
  AvgDialog_65480_Content_40 = {
    Text = "Refakatler seni ondan hızla ayırıyor, bedenine daha fazla kısıtlama ekliyorlar."
  },
  AvgDialog_65480_Content_41 = {
    Text = "Hiçbir direnç göstermiyor, gerçek bir kukla kadar uysal; ama o gözler sende sabitlenmiş kalıyor, her şeyi delip geçerek, sanki ruhunun izini sonsuza dek sürecekmiş gibi."
  },
  AvgDialog_65480_Content_42 = {
    Text = "Özlemle beklenen bir kavuşmayı bekler gibi."
  },
  AvgDialog_65480_Content_43 = {
    Text = "Mythag’ın sızmasının gerçeği nihayet zihninde bir araya geliyor."
  },
  AvgDialog_65480_Content_44 = {
    Text = "Mührü kıran, Juliette ile bağlantı kuran ve Mythag'a Girmenin yolunu sağlayan oydu."
  },
  AvgDialog_65480_Content_45 = {
    Text = "Juliette Kapıyı açtıktan sonra, gölgeler içinde Yüce İrade’nin bakışını yönlendiren yine oydu."
  },
  AvgDialog_65480_Content_46 = {
    Text = "Ve köstebeği araştıran Doll..."
  },
  AvgDialog_65480_Content_47 = {
    Text = "Doll nerede?"
  },
  AvgDialog_65480_Content_48 = {
    Text = "Doll nerede... Ona ne yaptın?!"
  },
  AvgDialog_65480_Content_49 = {
    Text = "Yeterince zeki ki, benim Kaçış’ımla ilgili seni uyarmak için acele etmeseydi, tuzağıma düşmeyecekti."
  },
  AvgDialog_65480_Content_5 = {
    Text = "Gözlerini, Kukla’ya tıpatıp benzeyen bu Uyanışçı’ya dikiyorsun. Buz gibi sesi, koyu, kaçınılmaz bir kötülükle damlıyor."
  },
  AvgDialog_65480_Content_50 = {
    Text = "Sana güvendi. Hatası buydu.\nYanlış kişiye güvenmenin bir bedeli vardır. Katılmıyor musun, Koruyucu?"
  },
  AvgDialog_65480_Content_51 = {
    Text = "Elini sallayıp çevirirken, rahat bir edayla elinde bir beyin tankı savurur."
  },
  AvgDialog_65480_Content_52 = {Text = "Bu...!"},
  AvgDialog_65480_Content_53 = {
    Text = "Bilinci tankın içinde hapsolmuşken, o yedek bedenlerin hiçbir işe yaramaz."
  },
  AvgDialog_65480_Content_54 = {
    Text = "Merak etme, ölemez—ve ölmesine izin vermeyeceğim.\nKorumaya çalıştığı her şeyin yıkılışını izlemesini istiyorum."
  },
  AvgDialog_65480_Content_55 = {
    Text = "Hepinizi haksız çıkaracağım."
  },
  AvgDialog_65480_Content_56 = {
    Text = "O mühür Mythag’ın kurucuları ve Tawil tarafından yaratılmıştı... Bunu nasıl yapabildin..."
  },
  AvgDialog_65480_Content_57 = {
    Text = "Mythag üzerindeki mühür gerçekten zahmetliydi. Ama böylesine çetrefilli bir mühür için bile, üzerine bu kadar düşünmem, bir çözüm tasarlamam için yeterli oldu."
  },
  AvgDialog_65480_Content_58 = {
    Text = "Tek yapmam gereken bedenimi İmha Etmek, sonra da Doll’un yedeklerinden birine geçmekti. Basit, değil mi?"
  },
  AvgDialog_65480_Content_59 = {
    Text = "Bir dahaki sefere, biraz daha kararlı olup beynimi ezip geçer misin? Ama ne yazık ki, bir dahaki sefer olmayacak."
  },
  AvgDialog_65480_Content_6 = {
    Text = "—Bu yüzü tanıyorsun. Bir aydan biraz daha uzun süre önce, Kukla’nın kılığına girerek Mythag’a sızdı, bir dizi vahşi olayı planladı, hatta bir Gümüş bomba ile devasa bir D-yarık tetiklemeye bile yaklaştı."
  },
  AvgDialog_65480_Content_60 = {
    Text = "Kampüsün dışındaki sisi dağıtmak, Kara Havuz’u sabote etmek, Yüce İrade’yi buraya çekmek... Bunların hepsi senin işin miydi?"
  },
  AvgDialog_65480_Content_61 = {
    Text = "Ben yaptım. Şimdi, sadece son bir adım kaldı."
  },
  AvgDialog_65480_Content_62 = {
    Text = "Dudakları hafifçe kıvrılır, keskin bir diş ortaya çıkar."
  },
  AvgDialog_65480_Content_63 = {
    Text = "İşaretçiyi yerleştirdim. Burasını görüyor—seni görüyor. O Kapı bir daha kapatılamaz."
  },
  AvgDialog_65480_Content_64 = {
    Text = "Kaybettin, Koruyucu."
  },
  AvgDialog_65480_Content_65 = {
    Text = "Arkasından devasa bir kükreme kopar; patlayıcı rüzgârlar kan kırmızısı buklelerini savurur, zafer dolu kahkahası kulak zarlarını deler."
  },
  AvgDialog_65480_Content_66 = {
    Text = "Tohuwabohu’nun uyanışı hızlanıyor... Durdurun onu!"
  },
  AvgDialog_65480_Content_7 = {
    Text = "Kendi boyutunu yok ettikten sonra, bakışlarını sizinkine çevirdi.\nOnu kendi ellerinle Kara Havuz'un derinliklerine mühürledin."
  },
  AvgDialog_65480_Content_8 = {
    Text = "Masum insanları incitmek, yeni bir Çözünme kıvılcımı çakmak... \"Kukla\", neden?"
  },
  AvgDialog_65480_Content_9 = {
    Text = "Diğer boyuttaki Çözünme üzerine yaptığın Araştırma bir tür atılıma mı yol açtı?"
  },
  AvgDialog_65481_Content_1 = {Text = "Ayîn"},
  AvgDialog_65481_Content_10 = {Text = "Ramona..."},
  AvgDialog_65481_Content_11 = {
    Text = "Elini okşayıp huzursuzluğunu gizlemeye çalışıyor, sonra ona yumuşak bir gülümseme sunuyorsun."
  },
  AvgDialog_65481_Content_12 = {
    Text = "Senin için, hepiniz için... İçeri girmek zorundayım. Bu benim görevim."
  },
  AvgDialog_65481_Content_13 = {
    Text = "Koruyucu, geri döneceksin. Çözünme’yi yok edeceğimiz güne dek yanımda savaşacaksın... Verdiğin sözü unutma!"
  },
  AvgDialog_65481_Content_14 = {
    Text = "Ciddi bir ifadeyle başını sallıyorsun. Elini nazikçe parmaklarının arasından sıyırıp Kapı’ya dönüyorsun."
  },
  AvgDialog_65481_Content_15 = {Text = "Ding—"},
  AvgDialog_65481_Content_16 = {
    Text = "Göğsünden bir titreşim uğuldar. Gümüş Anahtar, bir tür rezonansla çekilmiş gibi, önünde süzülür."
  },
  AvgDialog_65481_Content_17 = {
    Text = "Gümüş Anahtar’dan yoğun bir gümüş ışık yayılıyor, sonra sönüyor."
  },
  AvgDialog_65481_Content_18 = {
    Text = "Alçak bir gümbürtü duyuyorsun. Dokununca hissedilmeyen, uçsuz bucaksız Kapı yavaşça aralanıyor."
  },
  AvgDialog_65481_Content_19 = {
    Text = "İçinden kara bir ışık dalgalanır, seni sarmalar."
  },
  AvgDialog_65481_Content_2 = {
    Text = "Açık Kapı, önünde sessizce duruyor; bir tür makabresk davetiye gibi."
  },
  AvgDialog_65481_Content_20 = {
    Text = "Kapı, İkiz Doğum, siluetler... Etrafındaki her şey yok oluyor. Siyah ışık seni yeni bir Boyut’a çekiyor."
  },
  AvgDialog_65481_Content_21 = {
    Text = "Dünyaya ait tüm izler siliniyor. Geriye yalnızca saf Karanlık kalıyor."
  },
  AvgDialog_65481_Content_22 = {Text = "..."},
  AvgDialog_65481_Content_23 = {Text = "@2@3..."},
  AvgDialog_65481_Content_24 = {Text = "..."},
  AvgDialog_65481_Content_26 = {
    Text = "Önünde bir ışık küresi belirir. Sonra ikincisi, üçüncüsü..."
  },
  AvgDialog_65481_Content_27 = {
    Text = "Sayısız küre üzerinde, bir karanlık uçurumda tek tek açılıp hemen ardından paramparça olan girift çiçekler gibi, kaleydoskopik Ana Renkler akıyor ve titreşiyor."
  },
  AvgDialog_65481_Content_28 = {
    Text = "O bitmek bilmeyen Doğuş ve ölüm döngülerinde, Ana Renk kavramlarının Gözlerinin önünde Dans edip Döngü’ye girdiğini görüyorsun;"
  },
  AvgDialog_65481_Content_29 = {
    Text = "Tüm kelimelerin baloncukların içinde tek bir noktada çöktüğünü, orada görkemli, sonsuz bir destan oluşturduğunu görüyorsun;"
  },
  AvgDialog_65481_Content_3 = {
    Text = "Başka bir boyuta saptırılan göz şimdilik yok oldu. Çatlaktan tekinsiz tonlar sızıyor, tereddütlü yüzüne uğursuz bir parıltı düşürüyor."
  },
  AvgDialog_65481_Content_30 = {
    Text = "Geçmişin, şimdinin ve geleceğin imgelerini görüyorsun. Varoluşun ve Yok Oluş’un her zaman çizelgesini görüyorsun."
  },
  AvgDialog_65481_Content_31 = {
    Text = "İçinde bir ışık filizleniyormuş gibi oluyor; iç organlarını ve zihnini delip geçiyor."
  },
  AvgDialog_65481_Content_32 = {
    Text = "Sagacity’nin Aeon’u... Chokmah... Da’at..."
  },
  AvgDialog_65481_Content_33 = {
    Text = "Söyle bana, Yüce İrade’yi nasıl yenebilirim? Onları nasıl koruyabilirim..."
  },
  AvgDialog_65481_Content_34 = {
    Text = "Hokmah-Daat. Bu isim, bu boşlukta berrakça yankılanıyor."
  },
  AvgDialog_65481_Content_35 = {
    Text = "Size sana doğru süzülüyor. Parmağını uzatıyor, ona saygıyla dokunuyorsun."
  },
  AvgDialog_65481_Content_36 = {Text = "Pıt—"},
  AvgDialog_65481_Content_37 = {
    Text = "Baloncuk, önünde sayısız küçük ışık zerresine ayrılarak patlıyor. Etrafında bir peçe gibi dönüyor, nazikçe bedenine sarılıyorlar."
  },
  AvgDialog_65481_Content_38 = {
    Text = "Bu başlangıçtır, sondur... Her şeydir..."
  },
  AvgDialog_65481_Content_39 = {
    Text = "Yüce İrade yenilgiye uğratılamaz."
  },
  AvgDialog_65481_Content_4 = {
    Text = "Koruyucu..."
  },
  AvgDialog_65481_Content_40 = {
    Text = "Her bir baloncuğun içinden, zihninin derinliklerinden, bulanık bir Uzak Ses yankılanıyor."
  },
  AvgDialog_65481_Content_41 = {
    Text = "Hayır... Hayat, uygarlık, duygular... Dünyamız böyle sona eremez!"
  },
  AvgDialog_65481_Content_42 = {
    Text = "Bak bana. Kulak ver bana. Gözbebeksiz Göz’ün Parça’sı. Gözbebeksiz Göz’ün bilinci. Gözbebeksiz Göz’ün Gölge’si..."
  },
  AvgDialog_65481_Content_43 = {
    Text = "Bilinç, gölge... Ne demek istiyorsun?"
  },
  AvgDialog_65481_Content_44 = {
    Text = "Başını kaldırıyor, önündeki sayısız hayali baloncuğa bakıyorsun."
  },
  AvgDialog_65481_Content_45 = {
    Text = "Kapı, O uyanmadan önce kapatılmalı. Yüce İrade’yi yeniden hafif uykuya yatır. Dünyan geçici bir nefes alacak."
  },
  AvgDialog_65481_Content_46 = {
    Text = "Gölgenin Otoritesi’ni geri al, böylece Kapı’yı mühürleyecek gücü elde edeceksin."
  },
  AvgDialog_65481_Content_47 = {
    Text = "Dünyan, sevdiklerin... Yüce İrade’nin Parçası’nın gücüne dayanamazlar."
  },
  AvgDialog_65481_Content_48 = {
    Text = "Her şeyden vazgeçeceksin, Kapı'yı sonsuza dek koruyacaksın.\nYok olacaksın, bilinçsiz karanlıkta sonsuz çağlara katlanarak..."
  },
  AvgDialog_65481_Content_49 = {
    Text = "Gözbebeksiz Göz’ün Parça’sı, bu... ödemen gereken bedel."
  },
  AvgDialog_65481_Content_5 = {
    Text = "Senin geri döndüğünü görünce başını eğiyor, ama kolunu tutan eli hiç gevşemiyor."
  },
  AvgDialog_65481_Content_50 = {
    Text = "Önündeki kabarcığın üzerinde kendi yüzün belirir."
  },
  AvgDialog_65481_Content_51 = {
    Text = "Soğuk ter o yüzden aşağı süzülüyor. Titriyor—soğuktan, dehşetten."
  },
  AvgDialog_65481_Content_52 = {
    Text = "O eksik, uzatılmış ölümü; tüm hayatı Delilik’e sürükleyecek o ebedi yalnızlığı gözünün önüne getiriyorsun."
  },
  AvgDialog_65481_Content_53 = {
    Text = "Başka bir yol yok mu...? Ramona’ya söz verdim, onlara söz verdim..."
  },
  AvgDialog_65481_Content_54 = {
    Text = "Sayısız gözü açıldı. O'nun Gücü'ne diren, Kapı'yı mühürle ve O'nu yeniden hafif uykuya döndür. Tek yol bu."
  },
  AvgDialog_65481_Content_55 = {
    Text = "Şimdi seç."
  },
  AvgDialog_65481_Content_56 = {
    Text = "Zaman sanki Dondurma’ya uğramış gibi duruyor. Sonunda, etrafında dönen hayali Ana Renkleri seçebiliyorsun."
  },
  AvgDialog_65481_Content_57 = {
    Text = "Onlar, Anılarındaki her sahneyi taşır."
  },
  AvgDialog_65481_Content_58 = {
    Text = "Gümüş Anahtar’ı ilk kavrayışın... Bir Uyandırma yapanla kurduğun ilk bağ... İlk kez bir D-yarık’ı kapatışın..."
  },
  AvgDialog_65481_Content_59 = {
    Text = "Sayısız imge, sayısız yüz, sana bakıyor."
  },
  AvgDialog_65481_Content_6 = {Text = "Ramona?"},
  AvgDialog_65481_Content_60 = {
    Text = "Derin bir nefes alır ve başını kaldırırsın."
  },
  AvgDialog_65481_Content_61 = {
    Text = "Ben... Ben yapacağım."
  },
  AvgDialog_65481_Content_62 = {
    Text = "Ben... Ben yapacağım."
  },
  AvgDialog_65481_Content_63 = {
    Text = "Kendin olan her şeye veda et, Gözbebeksiz Göz’ün Parça’sı.\nYanında, yalnızca Otorite ve Anılar’dan dövülmüş şuursuz varlıklar kalacak."
  },
  AvgDialog_65481_Content_64 = {
    Text = "Uyandırma yapanlarla olan bağlarını kendi El’inle kopar.\nBırak, bedenin tek başına saf Kaos’a ve Karanlık’a Dönüş yapsın."
  },
  AvgDialog_65481_Content_65 = {
    Text = "Bundan sonra, üç Eon’un Otoritesi’ni Absorbe Et’mende sana yardım edeceğim."
  },
  AvgDialog_65481_Content_66 = {
    Text = "Seni bir Tanrıya dönüşmende destekleyeceğim."
  },
  AvgDialog_65481_Content_7 = {
    Text = "İçime kötü bir his doğdu..."
  },
  AvgDialog_65481_Content_8 = {
    Text = "Öteki ben sayısız Seçim’e tanıklık etti. Onun Anıları bende yok, ama..."
  },
  AvgDialog_65481_Content_9 = {
    Text = "Bu Kapı’nın ardında ne varsa... görmek isteyeceğim şey olmayacağını biliyorum..."
  },
  AvgDialog_65482_Content_1 = {
    Text = "Mythag benimle birlikte savaşmaya söz verdi... Gezegen’in sonuna dek birlikte savaşmaya."
  },
  AvgDialog_65482_Content_10 = {
    Text = "Artık kontrol altında olmayacağım, kimseye zarar vermeyeceğim ve arkadaşlarımın benim yüzümden ölmesine izin vermeyeceğim."
  },
  AvgDialog_65482_Content_11 = {
    Text = "Bana ne söylediğini hatırlıyor musun?"
  },
  AvgDialog_65482_Content_12 = {
    Text = "Sen demiştin ki... Asla yalnız değildim. Hâlâ yanında olduğunuzu söylemiştin. Hâlâ yanımda olan herkesin."
  },
  AvgDialog_65482_Content_13 = {
    Text = "O andan itibaren, biliyordum..."
  },
  AvgDialog_65482_Content_14 = {
    Text = "Senin için her şeyi yaparım."
  },
  AvgDialog_65482_Content_15 = {
    Text = "Sağ olun, hepinize teşekkürler... Son bir şey..."
  },
  AvgDialog_65482_Content_16 = {
    Text = "Beni unutma, olur mu?"
  },
  AvgDialog_65482_Content_17 = {
    Text = "Beni unutma, olur mu?"
  },
  AvgDialog_65482_Content_18 = {
    Text = "Resifin üzerine tünemiş haldeyken, kız aniden doğrudan sana bakar."
  },
  AvgDialog_65482_Content_19 = {
    Text = "Onun gözlerinde ışık zerrecikleri dans eder; o genç yüzde olağanüstü parlaklıkta bir gülümseme filizlenir."
  },
  AvgDialog_65482_Content_2 = {
    Text = "Bilseydim... Seninle asla bir pakt yapmazdım..."
  },
  AvgDialog_65482_Content_20 = {
    Text = "Zaman tarafından hapsedilmiş, mevsimini yitirmiş bir lily—"
  },
  AvgDialog_65482_Content_21 = {
    Text = "Tomurcuğun açılma anı sonunda geldi."
  },
  AvgDialog_65482_Content_22 = {
    Text = "Tomurcuğun açılma anı sonunda geldi."
  },
  AvgDialog_65482_Content_23 = {
    Text = "Başardım... Gerçekten başardım."
  },
  AvgDialog_65482_Content_24 = {
    Text = "Ben... onu deldim... Doğmayacak..."
  },
  AvgDialog_65482_Content_25 = {
    Text = "O zaman... Onlar..."
  },
  AvgDialog_65482_Content_26 = {
    Text = "Bıçağı kavrayan el güçsüzce düşüyor; kızıl, koyu ve yoğun bir sıvı bıçaktan akarak parmaklarının arasından denize damlıyor."
  },
  AvgDialog_65482_Content_27 = {
    Text = "Kan hızla bedeninden tükeniyor; Murphy’nin teni ölümcül bir solukluğa bürünüyor, yine de tuhaf bir canlılık saçıyor."
  },
  AvgDialog_65482_Content_28 = {
    Text = "Kan hızla bedeninden tükeniyor; Murphy’nin teni ölümcül bir solukluğa bürünüyor, yine de tuhaf bir canlılık saçıyor."
  },
  AvgDialog_65482_Content_29 = {
    Text = "Sonsuz Karanlık’ta bile, Umut Işığı Faint bile olsa... İnsanlar asla boyun eğmez; yalnızca o Ruh, yazgılı gelecekleri değiştirebilir."
  },
  AvgDialog_65482_Content_3 = {
    Text = "Mythag’ın geleceğini üzerine bahse koyduğu bu dahinin değerine Sadece Kendim İçin tanık olayım!"
  },
  AvgDialog_65482_Content_30 = {
    Text = "Şimdi, yeni bir cevap buldum."
  },
  AvgDialog_65482_Content_31 = {
    Text = "Öyleyse Tawil, seçtiğin varisi bana ödünç ver. Cömert ol biraz, olur mu?"
  },
  AvgDialog_65482_Content_32 = {
    Text = "Tohumumu {Male=ona,Female=ona} emanet edeceğim."
  },
  AvgDialog_65482_Content_33 = {
    Text = "Tohum kök salacak, filizlenecek, güzel bir ağaca dönüşecek—"
  },
  AvgDialog_65482_Content_34 = {
    Text = "İlk Ana Ağaç’ın doğduğu zamanki gibi."
  },
  AvgDialog_65482_Content_35 = {Text = "..."},
  AvgDialog_65482_Content_36 = {
    Text = "Bu son Tohum’u—onu senin içine ekiyorum."
  },
  AvgDialog_65482_Content_37 = {
    Text = "Kanımı toprağa saçana dek, sen ölmeyeceksin..."
  },
  AvgDialog_65482_Content_38 = {
    Text = "Beni hatırlayacaksın. Asla Unutma beni."
  },
  AvgDialog_65482_Content_39 = {
    Text = "Gelgitler Dalgalanma’ya geçiyor."
  },
  AvgDialog_65482_Content_4 = {
    Text = "Mythag’ın geleceğini üzerine bahse koyduğu bu dahinin değerine Sadece Kendim İçin tanık olayım!"
  },
  AvgDialog_65482_Content_40 = {
    Text = "O sıcak Kucaklayış seni kendinden itiyor."
  },
  AvgDialog_65482_Content_41 = {
    Text = "Akıntının yuvarlanan hücumu içinde, onun nehrin derinliklerine doğru sürüklendiğini görürsün."
  },
  AvgDialog_65482_Content_42 = {
    Text = "Akıntının yuvarlanan hücumu içinde, onun nehrin derinliklerine doğru sürüklendiğini görürsün."
  },
  AvgDialog_65482_Content_43 = {
    Text = "Şimdi mi? Burada mı?"
  },
  AvgDialog_65482_Content_44 = {
    Text = "Belki planladığımızdan biraz erken, ama bunun bir sakıncası olmamalı, değil mi?"
  },
  AvgDialog_65482_Content_45 = {
    Text = "Ayrıca, bu günü bir yılı aşkın süredir sabırsızlıkla bekliyordum."
  },
  AvgDialog_65482_Content_46 = {
    Text = "Yağmur damlaları eldivenlerine sızıyor, parmak uçlarını ıslatıyor; hafif bir akım kumaştan süzülerek teninle onunkinin arasında gizlice akıyor."
  },
  AvgDialog_65482_Content_47 = {
    Text = "Açıklanamaz duygular sinirlerinde dalgalanıyor—sevinç, heyecan, huzursuzluk ve..."
  },
  AvgDialog_65482_Content_48 = {
    Text = "...<Yellow:Umut>."
  },
  AvgDialog_65482_Content_49 = {
    Text = "Ne kadar sıcak... bağlantı kusursuz. Ruhun ve can gücün hiç olmadığı kadar parlak."
  },
  AvgDialog_65482_Content_5 = {
    Text = "Sorun değil, Muhafız."
  },
  AvgDialog_65482_Content_50 = {
    Text = "Sende <Yellow:biricik ve eşsiz> Koruyucu titrememeli. Çözünme’ye karışmış tüm kayıp tarihleri araştırıp kayda geçirmek için sana güveniyoruz."
  },
  AvgDialog_65482_Content_51 = {
    Text = "Ramona güven veren yarım bir gülümseme sundukça, gözlerindeki endişe silinir."
  },
  AvgDialog_65482_Content_52 = {
    Text = "İnce ince yağan Yağmur’un sesi dünyayı dolduruyor."
  },
  AvgDialog_65482_Content_53 = {
    Text = "İnce ince yağan Yağmur’un sesi dünyayı dolduruyor."
  },
  AvgDialog_65482_Content_54 = {
    Text = "Ra... Ramona..."
  },
  AvgDialog_65482_Content_55 = {
    Text = "Anılar parça parça yok olur, yüzler birer birer silinir."
  },
  AvgDialog_65482_Content_56 = {
    Text = "Geçmiş hikâyeler zihninin kıyılarına sürgün edilir; başrolden gözlemciye kayarsın."
  },
  AvgDialog_65482_Content_57 = {
    Text = "Yürek parçalayan Pain yavaş yavaş uyuşuyor."
  },
  AvgDialog_65482_Content_58 = {
    Text = "Kendini yerden yükselirken, Yıldızlar’ın derinliklerine doğru yükselirken görürsün."
  },
  AvgDialog_65482_Content_59 = {
    Text = "Bir zamanlar yanında olan her şey gittikçe daha uzağa sürüklenir ve sonunda boşlukta kaybolur."
  },
  AvgDialog_65482_Content_6 = {
    Text = "Bir şövalyenin görevi başkalarını korumaktır. Hâlâ dayanabilirim!"
  },
  AvgDialog_65482_Content_60 = {
    Text = "Ramona yok. Koruyucu da yok."
  },
  AvgDialog_65482_Content_61 = {
    Text = "Buradan ayrıldığında, artık onlarla hiçbir bağın kalmayacak."
  },
  AvgDialog_65482_Content_62 = {
    Text = "...Anlıyorum, Hokmah-Daat."
  },
  AvgDialog_65482_Content_63 = {
    Text = "Başını kaldırırsın. Bu sonsuz kabarcık diyarında, bedensiz ilahi varlıkla sohbet edersin."
  },
  AvgDialog_65482_Content_64 = {
    Text = "Bana adını söyle."
  },
  AvgDialog_65482_Content_65 = {
    Text = "Ben %player%’im. Ben Koruyucu’yum. Ben... Göz Bebeği Olmayan Göz’üm."
  },
  AvgDialog_65482_Content_66 = {
    Text = "Görevin tamamlandı. Bu Boyut’tan ayrıl, Hokmah-Daat."
  },
  AvgDialog_65482_Content_67 = {
    Text = "Onu durduracağım."
  },
  AvgDialog_65482_Content_68 = {
    Text = "Kendimi... durduracağım."
  },
  AvgDialog_65482_Content_7 = {
    Text = "Bir şövalyenin görevi başkalarını korumaktır. Hâlâ dayanabilirim!"
  },
  AvgDialog_65482_Content_8 = {
    Text = "Az sonra neye dönüşeceğimden dehşete düşüyorum... Ama artık hiçbirinin önemi yok."
  },
  AvgDialog_65482_Content_9 = {
    Text = "Artık kontrol altında olmayacağım, kimseye zarar vermeyeceğim ve arkadaşlarımın benim yüzümden ölmesine izin vermeyeceğim."
  },
  AvgDialog_65948_Content_1 = {
    Text = "La la la la"
  },
  AvgDialog_65948_Content_2 = {
    Text = "Tanıdık duygularla bükülmüş sesi, anlaşılmaz mırıltılara dönüştü."
  },
  AvgDialog_65948_Content_3 = {Text = "...Ne?"},
  AvgDialog_65948_Content_4 = {
    Text = "@3'ın bakışı gerçekten Ulaştığında, her şey sona erecek. Nihai sonuçtan önce istediğin zaman Mythag tasmasını çıkarıp bana sarılabilirsin."
  },
  AvgDialog_65948_Content_5 = {
    Text = "Tepkini görmezden geliyor, kulaklarına sevda sözleri fısıldayan bir sevgili gibi, ateşli bir içtenlikle, çılgın davetini mırıldanıyor."
  },
  AvgDialog_65948_Content_6 = {
    Text = "Seni buradan izleyeceğim."
  },
  AvgDialog_65948_Content_7 = {
    Text = "Kısa süre sonra Doll senden ayrıldı ve daha fazla kısıtlandı. Hiçbir tepki göstermedi, gerçek bir kukla gibi uysal. Gözleri sana sabitlenmiş, her şeyi delip geçiyormuş gibi, sonsuza dek ruhunu takip ediyordu."
  },
  AvgDialog_65948_Content_8 = {
    Text = "Özlemle beklenen bir kavuşmayı bekler gibi."
  },
  AvgDialog_66597_Content_1 = {
    Text = "Mythag benimle birlikte savaşmaya söz verdi... Gezegen’in sonuna dek birlikte savaşmaya."
  },
  AvgDialog_66597_Content_10 = {
    Text = "Artık kontrol altında olmayacağım, kimseye zarar vermeyeceğim ve arkadaşlarımın benim yüzümden ölmesine izin vermeyeceğim."
  },
  AvgDialog_66597_Content_11 = {
    Text = "Bana ne söylediğini hatırlıyor musun?"
  },
  AvgDialog_66597_Content_12 = {
    Text = "Sen demiştin ki... Asla yalnız değildim. Hâlâ yanında olduğunuzu söylemiştin. Hâlâ yanımda olan herkesin."
  },
  AvgDialog_66597_Content_13 = {
    Text = "O andan itibaren, biliyordum..."
  },
  AvgDialog_66597_Content_14 = {
    Text = "Senin için her şeyi yaparım."
  },
  AvgDialog_66597_Content_15 = {
    Text = "Sağ olun, hepinize teşekkürler... Son bir şey..."
  },
  AvgDialog_66597_Content_16 = {
    Text = "Beni unutma, olur mu?"
  },
  AvgDialog_66597_Content_17 = {
    Text = "Beni unutma, olur mu?"
  },
  AvgDialog_66597_Content_18 = {
    Text = "Kız çocuk isteksizce üzerinden iner, bakışı göğsünde oyalanır.\nAşağı baktığında, uykuda bile taktığın Gümüş Anahtar’ın hafif bir titreşimle parladığını görürsün."
  },
  AvgDialog_66597_Content_19 = {Text = "Adın Ne?"},
  AvgDialog_66597_Content_2 = {
    Text = "Bilseydim... Seninle asla bir pakt yapmazdım..."
  },
  AvgDialog_66597_Content_20 = {
    Text = "<Blue:Lily>..."
  },
  AvgDialog_66597_Content_21 = {
    Text = "Bunu sevdin mi, Lily? Dokunmak ister misin?"
  },
  AvgDialog_66597_Content_22 = {Text = "Elbette."},
  AvgDialog_66597_Content_23 = {
    Text = "Lily dikkatlice anahtarın ucuna dokundu.\n\nBelki hayal gücündü ama gümüş anahtar bir an için parlamış gibi göründü."
  },
  AvgDialog_66597_Content_24 = {Text = "Vay..."},
  AvgDialog_66597_Content_25 = {
    Text = "Lily aniden sizi sıkıca kucakladı.\n\nKalbiniz yumuşadı ve kendinizi tutamayıp nazikçe başını okşadınız."
  },
  AvgDialog_66597_Content_26 = {
    Text = "Lily aniden sizi sıkıca kucakladı.\n\nKalbiniz yumuşadı ve kendinizi tutamayıp nazikçe başını okşadınız."
  },
  AvgDialog_66597_Content_27 = {
    Text = "Başardım... Gerçekten başardım."
  },
  AvgDialog_66597_Content_28 = {
    Text = "Ben... onu deldim... Doğmayacak..."
  },
  AvgDialog_66597_Content_29 = {
    Text = "O zaman... Onlar..."
  },
  AvgDialog_66597_Content_3 = {
    Text = "Mythag’ın geleceğini üzerine bahse koyduğu bu dahinin değerine Sadece Kendim İçin tanık olayım!"
  },
  AvgDialog_66597_Content_30 = {
    Text = "Bıçağı kavrayan el güçsüzce düşüyor; kızıl, koyu ve yoğun bir sıvı bıçaktan akarak parmaklarının arasından denize damlıyor."
  },
  AvgDialog_66597_Content_31 = {
    Text = "Kan hızla bedeninden tükeniyor; Murphy’nin teni ölümcül bir solukluğa bürünüyor, yine de tuhaf bir canlılık saçıyor."
  },
  AvgDialog_66597_Content_32 = {
    Text = "Kan hızla bedeninden tükeniyor; Murphy’nin teni ölümcül bir solukluğa bürünüyor, yine de tuhaf bir canlılık saçıyor."
  },
  AvgDialog_66597_Content_33 = {
    Text = "Sonsuz Karanlık’ta bile, Umut Işığı Faint bile olsa... İnsanlar asla boyun eğmez; yalnızca o Ruh, yazgılı gelecekleri değiştirebilir."
  },
  AvgDialog_66597_Content_34 = {
    Text = "Şimdi, yeni bir cevap buldum."
  },
  AvgDialog_66597_Content_35 = {
    Text = "Öyleyse Tawil, seçtiğin varisi bana ödünç ver. Cömert ol biraz, olur mu?"
  },
  AvgDialog_66597_Content_36 = {
    Text = "Tohumumu {Male=ona,Female=ona} emanet edeceğim."
  },
  AvgDialog_66597_Content_37 = {
    Text = "Tohum kök salacak, filizlenecek, güzel bir ağaca dönüşecek—"
  },
  AvgDialog_66597_Content_38 = {
    Text = "İlk Ana Ağaç’ın doğduğu zamanki gibi."
  },
  AvgDialog_66597_Content_39 = {Text = "..."},
  AvgDialog_66597_Content_4 = {
    Text = "Mythag’ın geleceğini üzerine bahse koyduğu bu dahinin değerine Sadece Kendim İçin tanık olayım!"
  },
  AvgDialog_66597_Content_40 = {
    Text = "Bu son Tohum’u—onu senin içine ekiyorum."
  },
  AvgDialog_66597_Content_41 = {
    Text = "Kanımı toprağa saçana dek, sen ölmeyeceksin..."
  },
  AvgDialog_66597_Content_42 = {
    Text = "Beni hatırlayacaksın. Asla Unutma beni."
