  },
  AvgDialog_98293_Content_2 = {
    Text = "Burası... Londinium'un sahil şeridi mi?"
  },
  AvgDialog_98293_Content_20 = {
    Text = "Kımıldamadın, çünkü Murphy’nin de Thais’in de burada olmaması gerektiğini çok iyi biliyordun."
  },
  AvgDialog_98293_Content_21 = {
